	["arrows"] = "des flèches",
	["beats down hard at the air with both hands, one after the other, quickly."] = "frappe l'air violemment des deux mains, l'une après l'autre, très vite.",
	["blinks slowly and looks down at their boots with a puzzled frown."] = "cligne lentement des yeux et regarde ses bottes en fronçant les sourcils, perplexe.",
	["blinks twice, slowly, at the fire."] = "cligne lentement des yeux deux fois en regardant le feu.",
	["blows gently across an open palm."] = "souffle doucement sur sa paume ouverte.",
	["bows their head and moves their lips silently, slowly, as if learning the words."] = "baisse la tête et remue les lèvres sans un son, lentement, comme pour apprendre les mots.",
	["bows their head and rocks slowly where they sit, matching the pace of something very old."] = "baisse la tête et se balance lentement, au rythme de quelque chose de très ancien.",
	["bows their head for a moment with their eyes shut tight, then opens one of them."] = "baisse la tête un instant, les yeux bien fermés, puis en ouvre un.",
	["bows their head politely to the nearest log in the fire."] = "incline poliment la tête devant la bûche la plus proche dans le feu.",
	["bows their head toward the fire."] = "incline la tête vers le feu.",
	["bows their head with a small, rueful smile."] = "baisse la tête avec un petit sourire contrit.",
	["bows their head."] = "incline la tête.",
	["bows three times, very small, from where they sit."] = "s'incline trois fois, à peine, sans se lever.",
	["braces both hands against an invisible rail and looks sharply down."] = "s'agrippe des deux mains à une rambarde invisible et regarde brusquement en bas.",
	["braces their shoulder against something heavy and shoves, teeth bared."] = "cale l'épaule contre quelque chose de lourd et pousse, les dents serrées.",
	["breaks an imaginary loaf in half and holds one piece out across the fire."] = "rompt en deux une miche imaginaire et en tend un morceau par-dessus le feu.",
	["breaks off a crumb and sets it carefully on one knee, without looking."] = "détache une miette et la pose délicatement sur un genou, sans regarder.",
	["breaks off and turns one long ear toward the dark, utterly still."] = "s'interrompt et tourne une longue oreille vers l'obscurité, parfaitement immobile.",
	["breaks off and turns their head very slowly, as if someone had spoken just behind them."] = "s'interrompt et tourne la tête très lentement, comme si quelqu'un venait de parler juste derrière.",
	["breathes in the drifting woodsmoke and closes their eyes."] = "respire la fumée qui dérive et ferme les yeux.",
	["breathes in the woodsmoke and, for a moment, seems to catch the smell of fresh bread instead."] = "respire la fumée du feu de bois et, l'espace d'un instant, semble plutôt sentir l'odeur du pain chaud.",
	["brings a fist up to their mouth, then lowers it again without a sound."] = "porte le poing à sa bouche, puis le baisse sans un bruit.",
	["brings their hands together once, very softly, then lets them part."] = "joint les mains une fois, tout doucement, puis les écarte.",
	["brushes one thumb in short, patient strokes across the palm of the other hand."] = "passe le pouce à petits gestes patients sur la paume de l'autre main.",
	["brushes the air in front of them with the side of one hand, slowly, like a broom."] = "balaie lentement l'air du tranchant de la main, comme avec un balai.",
	["brushes their own sleeve, then looks at their fingertips a moment too long."] = "frotte sa propre manche, puis regarde le bout de ses doigts un peu trop longtemps.",
	["but after the hunt, I take something away. What am I?"] = "mais après la chasse, j'emporte ce qu'on a laissé. Qui suis-je ?",
	["but take one more hit, and I fall to the ground. What am I?"] = "mais encaissez un coup de plus, et je tombe à vos pieds. Qui suis-je ?",
	["chews slowly and deliberately, eyes fixed on the dark beyond the firelight."] = "mâche lentement, méthodiquement, les yeux rivés sur le noir au-delà du feu.",
	["chuckles and pats their stomach."] = "glousse et se tapote le ventre.",
	["chuckles low in their throat."] = "rit tout bas, du fond de la gorge.",
	["claps a hand to the top of their head, then slowly lowers it, finding nothing."] = "plaque une main sur le sommet de son crâne, puis la redescend lentement, vide.",
	["clasps their hands around an imagined rod and draws their shoulders back."] = "serre les mains autour d'une canne à pêche imaginaire et rejette les épaules en arrière.",
	["clears their throat and waits for the circle to go quiet."] = "s'éclaircit la gorge et attend que le cercle fasse silence.",
	["clenches both fists tight, then throws them open."] = "serre les deux poings, puis les ouvre d'un coup.",
	["closes a fist around the washer, and the firelight goes out of it."] = "referme le poing sur la rondelle, et la lueur du feu s'y éteint.",
	["closes both hands around an invisible rim and lowers their eyes."] = "referme les deux mains sur un bord invisible et baisse les yeux.",
	["closes one hand slowly into a fist."] = "serre lentement le poing.",
	["closes the hand slowly and rests it on one knee."] = "referme lentement la main et la pose sur un genou.",
	["closes their eyes and nods slowly, keeping a beat that isn't there."] = "ferme les yeux et hoche lentement la tête, en suivant une cadence qui n'existe pas.",
	["closes their eyes and sits quietly, as if a great field lay all around them."] = "ferme les yeux et se tient immobile, en silence, comme au milieu d'une immense prairie.",
	["closes their eyes for a moment."] = "ferme les yeux un instant.",
	["closes their hands, slowly, around nothing."] = "referme lentement les mains sur le vide.",
	["cocks their head to one side and blinks, first one eye and then the other."] = "penche la tête de côté et cligne des yeux, d'abord l'un, puis l'autre.",
	["conjured water"] = "de l'eau invoquée",
	["conjures a loaf, knocks on it, and winces at the sound."] = "invoque une miche de pain, frappe dessus et grimace en entendant le bruit.",
	["copper ore"] = "du minerai de cuivre",
	["coughs politely into one fist, then glances nervously behind them."] = "tousse poliment dans son poing, puis jette un regard inquiet par-dessus son épaule.",
	["coughs, and becomes very interested in the fire."] = "tousse, et se passionne soudain pour le feu.",
	["counts slowly on their fingers, and stops with one finger still raised."] = "compte lentement sur ses doigts, et s'arrête, un doigt encore levé.",
	["counts the questions off on their fingers and runs out of fingers."] = "compte les questions sur ses doigts, et finit par manquer de doigts.",
	["counts the steps off on their fingers, then wrinkles their nose."] = "compte les étapes sur ses doigts, puis fronce le nez.",
	["counts three points off on their fingers, then folds them away one by one."] = "compte trois points sur ses doigts, puis les replie un à un.",
	["cradles an invisible bowl in both hands, taking great care not to spill it."] = "tient un bol invisible au creux des deux mains, en prenant grand soin de ne rien renverser.",
	["cradles something small in both hands and turns it over very carefully."] = "tient quelque chose de petit au creux des deux mains et le retourne avec un soin infini.",
	["crumbles a heel of bread and lets it fall into the fire, one crumb at a time."] = "émiette un quignon de pain et le laisse tomber dans le feu, miette par miette.",
	["cups a hand as if holding something small and delicate."] = "arrondit la main comme pour y tenir quelque chose de petit et de fragile.",
	["cups a hand over one ear and turns their face from the fire."] = "couvre une oreille de sa main en coupe et détourne le visage du feu.",
	["cups a hand to one ear, as if listening to a far-off hum."] = "met une main en cornet à l'oreille, comme pour écouter un bourdonnement lointain.",
	["cups a hand to their mouth and makes a sound like a dying goose."] = "met une main en porte-voix et imite le cri d'une oie à l'agonie.",
	["cups an invisible flower in both hands, very carefully, as if it might fall apart."] = "tient une fleur invisible au creux des deux mains, avec mille précautions, comme si elle allait tomber en morceaux.",
	["cups an invisible lantern in both hands and mouths something at it, frowning."] = "tient une lanterne invisible au creux des mains et lui articule quelque chose en silence, les sourcils froncés.",
	["cups both hands together as if holding something small and damp."] = "referme les deux mains en coupe, comme sur quelque chose de petit et d'humide.",
	["cups both hands together, as if holding something very small."] = "joint les mains en coupe, comme pour tenir quelque chose de minuscule.",
	["cups both hands together, then opens them slowly."] = "joint les deux mains en coupe, puis les ouvre lentement.",
	["cups one hand behind an ear, looks left, then looks right with growing disbelief."] = "met une main en cornet derrière l'oreille, regarde à gauche, puis à droite, de plus en plus incrédule.",
	["cups one hand, as if holding something that might spill."] = "arrondit une main, comme pour tenir quelque chose qui pourrait déborder.",
	["cups their hands around their mouth and hoots softly."] = "met les mains en coupe autour de la bouche et hulule doucement.",
	["cups their hands gently, as though holding something small and warm."] = "arrondit doucement les mains, comme pour tenir quelque chose de petit et de chaud.",
	["curves one hand slowly through the air, as if guiding a growing branch."] = "trace lentement une courbe dans l'air, comme pour guider une branche qui pousse.",
	["dabs their forehead and looks hopefully into an empty box."] = "se tamponne le front et jette un regard plein d'espoir dans une boîte vide.",
	["dangles a sock over the flames on a stick, feels it, and shakes their head."] = "tend une chaussette au-dessus des flammes au bout d'un bâton, la tâte, et secoue la tête.",
	["dips their head to an invisible rock with exaggerated courtesy, then again with real courtesy."] = "s'incline devant un caillou invisible avec une politesse exagérée, puis à nouveau, avec une politesse sincère.",
	["drags a heavy pack closer and gives it a thump."] = "rapproche un lourd paquetage et lui donne une tape.",
	["drags a stick slowly through the ashes, clearing a line, and says nothing yet."] = "passe lentement un bâton dans les cendres pour tracer une ligne, sans rien dire encore.",
	["draws a crooked line in the ashes with a stick, then tilts their head to read it upside down."] = "trace une ligne tordue dans les cendres avec un bâton, puis penche la tête pour la lire à l'envers.",
	["draws a faded blue ribbon from inside their sleeve and looks at it without speaking."] = "tire de sa manche un ruban bleu délavé et le regarde sans un mot.",
	["draws a long breath and squares their shoulders, as though walking into a wind."] = "prend une longue inspiration et carre les épaules, comme pour marcher contre le vent.",
	["draws a quick blade across the air and pulls one hand sharply free."] = "tranche l'air d'un coup de lame rapide et dégage brusquement une main.",
	["draws a slow circle in the air with one finger, and lets it fade."] = "trace lentement un cercle dans l'air du bout du doigt, et le laisse s'effacer.",
	["draws a slow line through the air with one finger."] = "trace lentement une ligne dans l'air du bout du doigt.",
	["draws a slow, grinning face in the air with one finger."] = "dessine lentement dans l'air, du bout du doigt, un visage au large sourire.",
	["draws a straight line in the ashes with a stick, then slowly bends it into a curve."] = "trace une ligne droite dans la cendre avec un bâton, puis la courbe lentement.",
	["draws an imaginary arrow, then pauses to count the rest with one finger."] = "tire une flèche imaginaire du carquois, puis s'interrompt pour compter les autres du doigt.",
	["draws an imaginary purse from their coat and weighs it thoughtfully in one palm."] = "tire une bourse imaginaire de son manteau et la soupèse d'un air pensif dans une paume.",
	["draws back an invisible bowstring."] = "tend une corde d'arc invisible.",
	["draws back, takes a deep breath, and flings both arms wide."] = "recule, prend une grande inspiration et ouvre grand les bras.",
	["draws both hands in close, as if wrapping something tight around a pair of shoulders."] = "rapproche les deux mains, comme pour serrer un tissu autour de deux épaules.",
	["draws five small circles in the ashes with a stick, spacing them out."] = "trace cinq petits cercles dans la cendre avec un bâton, bien espacés.",
	["draws one hand back and forth in slow, patient strokes."] = "fait aller et venir une main, à coups lents et patients.",
	["draws one short line in the ashes with a stick and studies it."] = "trace un petit trait dans la cendre avec un bâton et l'examine.",
	["draws the coals closer with a short stick and watches the smaller glow."] = "rapproche les braises avec un petit bâton et contemple la lueur, plus modeste.",
	["draws their shoulders inward and holds utterly still."] = "rentre les épaules et se fige, parfaitement immobile.",
	["draws up their knees, lowers their head, and breathes out slowly."] = "ramène les genoux contre sa poitrine, baisse la tête et expire lentement.",
	["drops a splinter of wood into the coals and watches it go dark."] = "laisse tomber un éclat de bois dans les braises et le regarde s'éteindre.",
	["ducks sharply forward, one arm flung out behind them."] = "plonge brusquement en avant, un bras rejeté en arrière.",
	["ducks sharply, as though a stool just sailed over their head."] = "se baisse brusquement, comme si un tabouret venait de lui passer au-dessus de la tête.",
	["dusts off their hands with great dignity."] = "s'époussette les mains avec une grande dignité.",
	["eases a fresh log onto the fire with great care, as one might tuck in something sleeping."] = "pose une bûche neuve sur le feu avec un soin infini, comme on borde quelque chose qui dort.",
	["edges a little closer to the flames and rubs both arms."] = "se rapproche un peu des flammes et se frotte les bras.",
	["edges back from the flames, tugs at their collar, and fans themselves furiously."] = "recule un peu du feu, tire sur son col, et s'évente frénétiquement.",
	["fans out an invisible hand of cards and counts them twice."] = "déploie en éventail des cartes invisibles et les compte deux fois.",
	["fans out an invisible hand of cards and scowls at it."] = "déploie en éventail une main de cartes invisible et la fusille du regard.",
	["fans their face with one hand."] = "s'évente le visage d'une main.",
	["fans their open mouth with one hand, eyes watering."] = "s'évente la bouche grande ouverte d'une main, les yeux pleins de larmes.",
	["feeds a thin stick to the flames and watches it catch."] = "donne une brindille au feu et la regarde s'embraser.",
	["feeds one more stick to the flames, unhurried, so the fire stands a little taller against the dark."] = "ajoute encore un bâton aux flammes, sans se presser, pour que le feu se dresse un peu plus haut contre la nuit.",
	["feeds the fire a larger stick, glaring at a spot near their knee."] = "remet une plus grosse branche dans le feu en foudroyant du regard un point près de son genou.",
	["feeds the fire one more stick, though no one needs it, just in case."] = "remet un bâton dans le feu, même si personne n'en a besoin, au cas où.",
	["feels forward with one hand, slowly, as though blind."] = "tâtonne dans le vide d'une main, lentement, comme à l'aveugle.",
	["flexes one hand, as if still feeling the fight in it."] = "serre et desserre une main, comme si le combat y vibrait encore.",
	["flexes their off hand and looks at it as though it were an old friend."] = "fait jouer sa main faible et la regarde comme une vieille amie.",
	["flicks an imaginary speck of ash from their sleeve."] = "chasse d'une pichenette une poussière de cendre imaginaire sur sa manche.",
	["flinches and wipes the side of their face."] = "sursaute et s'essuie la joue.",
	["flinches as a log cracks and settles in the fire, then lays their hand back on their knee, one finger at a time."] = "tressaille quand une bûche craque et se tasse dans le feu, puis repose la main sur son genou, un doigt après l'autre.",
	["flinches back, as if from a sudden burst of shadow."] = "recule d'un coup, comme devant une soudaine gerbe d'ombre.",
	["flinches from a popping spark and pats their singed eyebrows."] = "sursaute au claquement d'une étincelle et se tapote les sourcils roussis.",
	["flinches hard to one side, throwing an arm over their head."] = "fait un bond brusque sur le côté, un bras jeté par-dessus la tête.",
	["flings a handful of dry grass on the fire and grins as it flares."] = "jette une poignée d'herbe sèche dans le feu et sourit quand elle s'embrase.",
	["flips a coin and catches it on the back of their hand."] = "lance une pièce en l'air et la rattrape sur le dos de la main.",
	["flips an invisible coin and catches it on the back of one hand."] = "fait sauter une pièce invisible et la rattrape sur le dos de la main.",
	["flutters their fingers downward like falling snow."] = "fait voleter ses doigts vers le bas, comme de la neige qui tombe.",
	["folds an invisible scrap of paper small, then tucks it low with one finger."] = "plie tout petit un bout de papier invisible, puis le glisse au ras du sol, du bout du doigt.",
	["folds an invisible sheet of paper in half, then in half again."] = "plie en deux une feuille de papier invisible, puis encore en deux.",
	["folds one hand carefully over the other, as if tying the corners of a cloth."] = "replie soigneusement une main sur l'autre, comme pour nouer les coins d'un linge.",
	["folds their arms and frowns down at an imaginary traveler."] = "croise les bras et fronce les sourcils vers un voyageur imaginaire.",
	["folds their arms and stares into the fire with tremendous patience."] = "croise les bras et fixe le feu avec une patience colossale.",
	["folds their hands and nods with immense, unhurried gravity."] = "joint les mains et hoche la tête avec une gravité immense et sans hâte.",
	["folds their hands and puts on a face of enormous patience."] = "croise les mains et prend un air d'une patience infinie.",
	["folds their hands in their lap."] = "croise les mains sur ses genoux.",
	["follows one spark up until it goes out, and looks back down without a word."] = "suit une étincelle des yeux jusqu'à ce qu'elle s'éteigne, puis baisse le regard sans un mot.",
	["frames a small square in the air with their fingers, and peers through it."] = "encadre un petit carré dans l'air avec les doigts et regarde au travers.",
	["free for the thirsty who wander about. What am I?"] = "gratuite pour l'assoiffé qui me boit au goulot. Qui suis-je ?",
	["freezes mid-motion, eyes sliding toward the ground."] = "se fige en plein geste, le regard glissant vers le sol.",
	["furrows their brow and thinks very slowly, tapping a finger on their chin."] = "fronce les sourcils et réfléchit très lentement, en se tapotant le menton du doigt.",
	["gathers a few twigs and lays them neatly at the edge of the fire."] = "ramasse quelques brindilles et les dépose soigneusement au bord du feu.",
	["gathers the invisible cards together and holds them against their chest."] = "rassemble les cartes invisibles et les serre contre sa poitrine.",
	["gazes down at their open hands as if weighing something."] = "baisse les yeux sur ses mains ouvertes, comme pour soupeser quelque chose.",
	["gazes into the flames, giving the question time to settle."] = "fixe les flammes, le temps que la question fasse son chemin.",
	["gazes off into the distance with great dignity."] = "fixe l'horizon avec une immense dignité.",
	["gazes solemnly into the distance, nodding, then looks down and sighs."] = "fixe gravement l'horizon en hochant la tête, puis baisse les yeux et soupire.",
	["gazes through the heat shimmer above the fire, as though something blue might lie on the other side."] = "regarde à travers l'air qui tremble au-dessus du feu, comme si quelque chose de bleu pouvait se trouver de l'autre côté.",
	["gives a satisfied nod and brushes their palms together."] = "hoche la tête d'un air satisfait et s'époussette les mains.",
	["gives a small, knowing smile."] = "esquisse un petit sourire entendu.",
	["gives the burning log in the fire a long, respectful look."] = "pose un long regard respectueux sur la bûche qui brûle dans le feu.",
	["gives the fire a small, apologetic nod, just in case."] = "adresse au feu un petit signe de tête navré, au cas où.",
	["gives {target} a good long look, then slides an invisible heel of bread across to them."] = "pose un long regard sur {target}, puis lui fait glisser un quignon de pain invisible.",
	["glances at the empty space beside them, and shifts over a little."] = "jette un œil à la place vide d'à côté, et se pousse un peu.",
	["glances at the empty space beside them, then leans in a little closer to the fire."] = "jette un regard à l'espace vide juste à côté, puis se rapproche un peu du feu.",
	["glances at the flames, and for a moment does not seem certain what color they are."] = "jette un regard aux flammes et, l'espace d'un instant, semble douter de leur couleur.",
	["glances at the sky, as if checking the hour."] = "jette un coup d'œil au ciel, comme pour vérifier l'heure.",
	["glances at their own shadow in the firelight, checking which way it falls."] = "jette un œil à sa propre ombre à la lueur du feu, pour voir de quel côté elle tombe.",
	["glances at {target}, then away, then back again."] = "jette un regard à {target}, détourne les yeux, puis regarde de nouveau.",
	["glances back at their own shadow, stretched long behind them, and does not look for long."] = "jette un coup d'œil à son ombre, étirée dans son dos, et ne s'y attarde pas.",
	["glances down at about knee height and gives a long-suffering sigh."] = "baisse les yeux à hauteur de genou et pousse un soupir de martyr.",
	["glances down at the campfire beside them and, very casually, shifts over a little."] = "jette un œil au feu de camp juste à côté et, l'air de rien, se décale un peu.",
	["glances left, then right, then leans closer."] = "regarde à gauche, puis à droite, puis se penche plus près.",
	["glances off toward the trees."] = "jette un regard vers les arbres.",
	["glances out at the dark beyond the firelight, then back at the circle."] = "jette un regard vers l'obscurité au-delà du feu, puis revient au cercle.",
	["glances out past the firelight, as if checking something."] = "jette un œil au-delà de la lueur du feu, comme pour vérifier quelque chose.",
	["glances out past the firelight, toward the dark between the trees."] = "jette un regard au-delà de la lueur du feu, vers le noir entre les arbres.",
	["glances over at {target} and tips their head."] = "jette un regard à {target} et incline la tête.",
	["glances over one shoulder, then back again."] = "jette un œil par-dessus son épaule, puis se retourne vers le feu.",
	["glances over one shoulder, then laughs a little too loudly."] = "jette un œil par-dessus son épaule, puis rit un peu trop fort.",
	["glances over one shoulder, then mimes sliding something carefully back onto a high shelf."] = "jette un œil par-dessus l'épaule, puis fait mine de reposer quelque chose avec soin tout en haut d'une étagère.",
	["glances over one shoulder, then pretends they didn't."] = "jette un coup d'œil par-dessus son épaule, puis fait comme si de rien n'était.",
	["glances over one shoulder, then turns back to the fire a little too quickly."] = "jette un coup d'œil par-dessus l'épaule, puis se retourne vers le feu un peu trop vite.",
	["glances past the firelight and counts something out there under their breath."] = "jette un regard au-delà de la lueur du feu et compte quelque chose, là-bas, à mi-voix.",
	["glances past {target} into the dark, and holds very still for a moment."] = "jette un regard dans le noir derrière {target}, et reste parfaitement immobile un moment.",
	["glances sideways at the empty space next to them, as if keeping pace with it."] = "jette un coup d'œil de côté, vers le vide, comme pour marcher au pas de quelqu'un.",
	["glances skyward out of habit."] = "jette un coup d'œil au ciel, par habitude.",
	["glances up at the branches overhead, as though one of them might move."] = "lève les yeux vers les branches au-dessus, comme si l'une d'elles allait bouger.",
	["glances up past the reach of the firelight, as if counting something overhead."] = "lève les yeux au-delà de la lueur du feu, comme pour compter quelque chose là-haut.",
	["glances up, as if at a high window, and flinches."] = "lève les yeux, comme vers une haute fenêtre, et tressaille.",
	["goes completely still for a long moment, barely breathing."] = "s'immobilise complètement un long moment, en respirant à peine.",
	["goes completely still, one hand flat at their side, eyes fixed on nothing."] = "se fige complètement, une main à plat sur le côté, le regard perdu dans le vide.",
	["goes quiet and lowers their eyes to the flames."] = "se tait et baisse les yeux vers les flammes.",
	["goes quiet, letting the crackle of the fire fill the place where the answer would be."] = "se tait et laisse le crépitement du feu prendre la place de la réponse.",
	["goes very still, and looks down at their empty hands."] = "se fige complètement et baisse les yeux sur ses mains vides.",
	["grabs at something over their shoulder and leans back with all their weight."] = "agrippe quelque chose par-dessus son épaule et se jette en arrière de tout son poids.",
	["grabs at the air with both hands, then wrenches them sharply to one side."] = "agrippe l'air à deux mains, puis braque d'un coup sec sur le côté.",
	["grins across the fire."] = "sourit de toutes ses dents par-dessus le feu.",
	["grins and takes a long, satisfied drink."] = "sourit jusqu'aux oreilles et boit une longue gorgée satisfaite.",
	["grins wide, showing every tooth, and holds it a little too long."] = "sourit de toutes ses dents, et garde ce sourire un peu trop longtemps.",
	["grins, then hides the grin behind one hand."] = "sourit, puis cache son sourire derrière une main.",
	["grips an imaginary set of levers and jerks them left and right."] = "empoigne des leviers imaginaires et les secoue de gauche à droite.",
	["grips an imagined club and gives one short, checked swing above their knee."] = "empoigne un gourdin imaginaire et esquisse un coup bref, retenu, au-dessus du genou.",
	["grips an invisible rope in both fists, and leans back hard."] = "serre une corde invisible à deux poings et se penche en arrière de toutes ses forces.",
	["grips an invisible sack by the neck and swings it round in a wide, low arc."] = "empoigne un sac invisible par le col et le fait tournoyer en un large arc, au ras du sol.",
	["grips an invisible staff that keeps trying to tilt to one side, and wrestles it upright."] = "agrippe un bâton invisible qui n'arrête pas de pencher d'un côté, et lutte pour le redresser.",
	["grips an invisible totem in both hands and drives it into the ground beside them."] = "empoigne à deux mains un totem invisible et l'enfonce dans le sol, juste à côté.",
	["grips reins and leans sharply to one side, cheeks puffed."] = "agrippe des rênes et se penche brusquement sur le côté, les joues gonflées.",
	["grunts, a smile tugging at one tusk."] = "grogne, un sourire au coin d'une défense.",
	["gurgles deep in their throat, then wipes their chin with great dignity."] = "gargouille du fond de la gorge, puis s'essuie le menton avec une grande dignité.",
	["hauls hand over hand on an invisible rope, leaning back."] = "hale une corde invisible main après main, en se penchant en arrière.",
	["hefts an invisible, very heavy volume in both hands and squares up."] = "soupèse à deux mains un volume invisible et très lourd, et se met en garde.",
	["holds a flat hand low, then lets it slowly rise and sway."] = "tient une main à plat près du sol, puis la laisse lentement remonter et onduler.",
	["holds a hand out over the coals, palm down, and slowly draws it back."] = "tend une main au-dessus des braises, paume vers le bas, puis la retire lentement.",
	["holds an invisible crate out at arm's length and leans their head away from it."] = "tient une caisse invisible à bout de bras et en écarte la tête.",
	["holds an invisible drawing out at arm's length and tilts their head at it."] = "tient un dessin invisible à bout de bras et penche la tête pour l'examiner.",
	["holds an invisible umbrella high overhead and squints up at it."] = "tient un parasol invisible bien haut et lève vers lui des yeux plissés.",
	["holds an invisible vial up to the light."] = "lève une fiole invisible vers la lumière.",
	["holds both arms out wide and lets them sink slowly, counting with small nods."] = "écarte grand les bras et les laisse descendre lentement, en comptant par petits hochements de tête.",
	["holds both hands close together above the warmth."] = "tient les deux mains rapprochées au-dessus de la chaleur.",
	["holds both hands out toward the flames."] = "tend les deux mains vers les flammes.",
	["holds both palms out toward the fire, as if feeling warmth from something unseen."] = "tend les deux paumes vers le feu, comme pour sentir la chaleur de quelque chose d'invisible.",
	["holds both palms toward the fire for a long moment, as if checking that they still feel it."] = "tend les deux paumes vers le feu un long moment, comme pour vérifier qu'elles le sentent encore.",
	["holds one boot out toward the flames and regards it with long-suffering sadness."] = "tend une botte vers les flammes et la contemple avec une tristesse résignée.",
	["holds one elbow up to the firelight and studies it for a long moment."] = "lève un coude vers la lueur du feu et l'examine longuement.",
	["holds one finger very still above an open palm, waiting."] = "tient un doigt parfaitement immobile au-dessus d'une paume ouverte, et attend.",
	["holds one forearm close against their chest, and reaches carefully up with the other."] = "serre un avant-bras contre sa poitrine, et tend l'autre vers le haut avec précaution.",
	["holds one hand flat above their head and squints up from beneath it."] = "tient une main à plat au-dessus de sa tête et lève les yeux en plissant les paupières.",
	["holds one hand halfway raised, eyes moving slowly left and right."] = "garde une main à demi levée, les yeux allant lentement de gauche à droite.",
	["holds one hand out to the fire, the other still on the pouch, and seems unsure which is warmer."] = "tend une main vers le feu, l'autre toujours sur la bourse, sans trop savoir laquelle a le plus chaud.",
	["holds one open palm out toward the fire, as if to have it read."] = "tend une paume ouverte vers le feu, comme pour se la faire lire.",
	["holds out a cupped hand and drops invisible nails into it, one at a time."] = "tend une main en coupe et y laisse tomber des clous invisibles, un par un.",
	["holds out a cupped hand, then slowly pushes it away."] = "tend une main en coupe, puis la repousse lentement.",
	["holds out a hand, as if feeling for a breeze."] = "tend une main, comme pour sentir une brise.",
	["holds out an empty palm toward the fire, hopefully."] = "tend une paume vide vers le feu, avec espoir.",
	["holds out an invisible pen across the fire toward {target}."] = "tend une plume invisible à {target} par-dessus le feu.",
	["holds out an invisible spoon toward {target} with both hands, like a knight offering a sword."] = "tend des deux mains une cuillère invisible à {target}, comme un chevalier qui offre son épée.",
	["holds out both hands and accepts something small, with visible surprise."] = "tend les deux mains et accepte quelque chose de minuscule, avec une surprise visible.",
	["holds out both hands and regards them quietly."] = "tend les deux mains et les contemple en silence.",
	["holds out both hands as if warming a coat before a fire, turning it slowly."] = "tend les deux mains comme pour réchauffer un manteau devant le feu, en le tournant doucement.",
	["holds out cupped hands toward {target}, as if passing a bowl across the fire."] = "tend les mains en coupe vers {target}, comme pour faire passer un bol par-dessus le feu.",
	["holds out cupped hands, very still."] = "tend les mains en coupe, sans bouger d'un cil.",
	["holds out one arm and scratches the air gently with the other hand."] = "tend un bras et gratte doucement l'air de l'autre main.",
	["holds out one arm, very still, and looks along it."] = "tend un bras, parfaitement immobile, et le suit du regard.",
	["holds out one hand as if guiding someone frail across a road."] = "tend une main, comme pour aider quelqu'un de fragile à traverser une route.",
	["holds out one open palm and watches it closely."] = "tend une paume ouverte et ne la quitte pas des yeux.",
	["holds still, then glances toward their own shadow and quickly back to the fire."] = "reste immobile, puis jette un œil vers sa propre ombre et revient vite au feu.",
	["holds the back of one hand up to the firelight so an old scar shows, and looks at it for a while."] = "lève le dos d'une main vers la lumière du feu pour montrer une vieille cicatrice, et la contemple un moment.",
	["holds the letter a moment too near the flames, then folds it carefully and tucks it away again."] = "tient la lettre un instant trop près des flammes, puis la replie avec soin et la range.",
	["holds their hands apart as though measuring a very fine pair of boots."] = "écarte les mains comme pour mesurer une très belle paire de bottes.",
	["holds their hands close to the flames, turns them over, and regards them in silence."] = "approche ses mains des flammes, les retourne, et les contemple en silence.",
	["holds their palms out to the flames and nods toward {target}'s side of the fire."] = "tend les paumes vers les flammes et désigne d'un signe de tête le côté du feu où se trouve {target}.",
	["holds two fingers very still, then twitches them a hair to one side, timing something."] = "tient deux doigts parfaitement immobiles, puis les décale d'un cheveu, en guettant le bon moment.",
	["holds two invisible halves apart and looks from one to the other."] = "écarte deux moitiés invisibles et regarde l'une, puis l'autre.",
	["holds up a hand and counts along their fingers, then starts on the other hand."] = "lève une main et compte sur ses doigts, puis passe à l'autre main.",
	["holds up a hand with the thumb and finger a few inches apart, and smiles."] = "écarte le pouce et l'index de quelques centimètres, et sourit.",
	["holds up a small steel washer between finger and thumb."] = "brandit une petite rondelle d'acier entre le pouce et l'index.",
	["holds up a thumb and finger, pinching something thin and small."] = "lève le pouce et l'index, comme pour pincer quelque chose de petit et de très fin.",
	["holds up a thumb and forefinger, barely apart."] = "lève le pouce et l'index, presque collés.",
	["holds up a thumb and squints along it, measuring someone from a distance."] = "lève un pouce et ferme un œil, comme pour mesurer quelqu'un de loin.",
	["holds up a tiny invisible stone and squints at it."] = "lève une minuscule pierre invisible et plisse les yeux pour l'examiner.",
	["holds up an imaginary blade, squints along it, and grimaces."] = "lève une lame imaginaire, vise le long du fil en plissant les yeux, et grimace.",
	["holds up an invisible carving and turns it around, frowning, trying another angle."] = "brandit une sculpture invisible et la fait tourner en fronçant les sourcils, cherchant un autre angle.",
	["holds up an invisible scrap between two fingers."] = "brandit un bout de tissu invisible entre deux doigts.",
	["holds up an invisible vial and squints at it against the firelight."] = "lève une fiole invisible et plisse les yeux pour l'examiner à la lueur du feu.",
	["holds up an invisible waterskin and shakes it, listening closely."] = "brandit une outre invisible et la secoue, l'oreille tendue.",
	["holds up one finger and lets the question hang in the smoke."] = "lève un doigt et laisse la question flotter dans la fumée.",
	["holds up one finger, as if the worst part is coming."] = "lève un doigt, comme si le pire restait à venir.",
	["holds up one finger, thinks better of it, and opens both hands."] = "lève un doigt, se ravise, et ouvre les deux mains.",
	["holds up one hand and slowly closes it into a loose fist, not a tight one."] = "lève une main et la referme lentement en un poing souple, sans serrer.",
	["holds up one hand as though steadying a lamp, and keeps it very still."] = "lève une main comme pour tenir une lampe bien droite, et la garde parfaitement immobile.",
	["holds up one hand with the fingers spread, studying it as though it belonged to someone else."] = "lève une main, doigts écartés, et l'observe comme si elle appartenait à quelqu'un d'autre.",
	["holds up something small between finger and thumb, turning it so the firelight slides along it."] = "tient une petite chose entre le pouce et l'index, et la tourne pour que la lueur du feu glisse dessus.",
	["holds up three fingers, then folds them down, one at a time."] = "lève trois doigts, puis les replie, un par un.",
	["holds up two empty fists and stares at them in remembered horror."] = "lève deux poings vides et les fixe, comme si toute l'horreur lui revenait.",
	["holds up two fingers, side by side, and gazes at them fondly."] = "lève deux doigts côte à côte et les contemple avec tendresse.",
	["holds up two fingers, then knocks them together."] = "lève deux doigts, puis les entrechoque.",
	["holds up two fingers, then slowly lowers one of them."] = "lève deux doigts, puis en abaisse un lentement.",
	["hums a few bars of an old marching song."] = "fredonne quelques mesures d'une vieille marche militaire.",
	["hums a few wandering notes that never quite settle into a song."] = "fredonne quelques notes vagabondes qui ne deviennent jamais tout à fait une chanson.",
	["hums the last notes again, more softly."] = "fredonne encore les dernières notes, plus doucement.",
	["hunches low and leans slowly forward, inch by inch."] = "se ramasse au ras du sol et avance lentement, centimètre par centimètre.",
	["hunches low and moves their hands slowly, as if sneaking."] = "courbe le dos et avance les mains très lentement, comme à pas de loup.",
	["hunches low, gripping the air on either side and refusing to look down."] = "se recroqueville, agrippe l'air de chaque côté et refuse de regarder en bas.",
	["hunches low, grips an invisible rim, and leans hard into a turn."] = "se recroqueville, agrippe un rebord invisible et se penche de tout son poids dans un virage.",
	["hunches low, one hand out for balance, and glances back with wide eyes."] = "se baisse très bas, une main tendue pour garder l'équilibre, et jette un regard en arrière, les yeux écarquillés.",
	["hunches their shoulders and bares their teeth, growling softly."] = "rentre la tête dans les épaules et montre les dents en grondant doucement.",
	["is quiet for a moment, then nods slowly."] = "garde le silence un instant, puis hoche lentement la tête.",
	["is quiet for a moment, watching the coals."] = "se tait un moment, les yeux sur les braises.",
	["is quiet for a moment."] = "se tait un moment.",
	["jabs a thumb over one shoulder, toward some ridge in the dark."] = "pointe le pouce par-dessus son épaule, vers quelque crête dans le noir.",
	["jerks forward suddenly, one arm wrenched out straight, teeth bared."] = "bascule soudain en avant, un bras tendu à s'en arracher, les dents découvertes.",
	["jerks one fist forward, then draws back an imagined blade with the other hand."] = "projette un poing en avant, puis ramène de l'autre main une lame imaginaire.",
	["keeps their eyes on the flames, as if still holding that light up for someone."] = "garde les yeux sur les flammes, comme pour éclairer encore quelqu'un dans le noir.",
	["keeps their gaze fixed on the ground as they speak."] = "garde les yeux rivés au sol en parlant.",
	["knocks twice on the ground beside them."] = "frappe deux fois le sol à ses côtés.",
	["laughs quietly into one hand."] = "rit tout bas derrière une main.",
	["lays an invisible flower down beside them, very carefully."] = "dépose une fleur invisible par terre, avec grand soin.",
	["lays one hand flat on the ground, then the other beside it."] = "pose une main à plat sur le sol, puis l'autre à côté.",
	["lays one hand flat, then sets the other on top of it, very carefully."] = "pose une main à plat, puis l'autre par-dessus, avec beaucoup de soin.",
	["leans back and looks toward the water."] = "se renverse en arrière et regarde vers l'eau.",
	["leans back and stretches both hands toward the warmth."] = "se laisse aller en arrière et tend les deux mains vers la chaleur.",
	["leans back with both hands behind their head."] = "se laisse aller en arrière, les mains derrière la tête.",
	["leans back, still studying {target}, one eye narrowed."] = "se cale en arrière, sans quitter {target} des yeux, un œil plissé.",
	["leans down and lays two fingers on the ground, then goes very still."] = "se penche et pose deux doigts sur le sol, puis se fige.",
	["leans down and presses one palm flat against the ground."] = "se penche et pose une paume bien à plat sur le sol.",
	["leans down and studies the ground, then glances up, smirking."] = "se penche pour étudier le sol, puis relève les yeux avec un sourire en coin.",
	["leans forward and lowers their voice, one eye on the dark beyond the fire."] = "se penche en avant et baisse la voix, un œil sur l'obscurité au-delà du feu.",
	["leans forward and pats their hands quickly against their knees, like feet on hard ground."] = "se penche en avant et tambourine vite des mains sur ses genoux, comme des pattes sur la terre dure.",
	["leans forward and works at an imaginary keyhole, tongue between their teeth."] = "se penche en avant et travaille une serrure imaginaire, la langue entre les dents.",
	["leans forward slightly, then back, then forward again, listening each time."] = "se penche légèrement en avant, puis en arrière, puis de nouveau en avant, en tendant l'oreille chaque fois.",
	["leans forward, pokes at something invisible with a stick, and sniffs thoughtfully."] = "se penche en avant, tâte quelque chose d'invisible du bout d'un bâton, et renifle d'un air pensif.",
	["leans forward, raises one hand, and waits, watching the ground."] = "se penche en avant, lève une main et attend, les yeux rivés au sol.",
	["leans hard to one side, arms braced, squinting into driving rain."] = "se penche fort d'un côté, les bras arc-boutés, en plissant les yeux sous une pluie battante.",
	["leans in and drops their voice, as if the captain might still overhear."] = "se penche et baisse la voix, comme si la capitaine pouvait encore entendre.",
	["leans in close to the fire and lowers their voice."] = "se penche tout près du feu et baisse la voix.",
	["leans in over the fire, so the light climbs their face, and lowers their voice."] = "se penche au-dessus du feu, pour que la lumière remonte sur son visage, et baisse la voix.",
	["leans lightly on an invisible pole, barely pressing."] = "s'appuie légèrement sur une perche invisible, sans presque forcer.",
	["leans out with arms spread for balance, and glances down at a long drop."] = "se penche dans le vide, les bras écartés pour garder l'équilibre, et jette un regard vers le bas, très loin.",
	["leans over and brushes something away with one hand, then looks closer."] = "se penche et chasse quelque chose d'un revers de main, puis regarde de plus près.",
	["leans over and lifts a stone with great care."] = "se penche et soulève une pierre avec grand soin.",
	["leans over and runs a hand across the grass, then wipes it on their coat."] = "se penche, passe une main dans l'herbe, puis l'essuie sur son manteau.",
	["leans over to peer in the direction of {target}'s boots, then winces."] = "se penche pour jeter un œil vers les bottes de {target}, puis grimace.",
	["leans sideways with arms outspread, one hand clutching an imaginary wrench."] = "se penche de côté, les bras écartés, une main serrée sur une clé à molette imaginaire.",
	["leans to one side and peers around something tall, then winces."] = "se penche d'un côté pour regarder derrière quelque chose de grand, puis grimace.",
	["leans toward the fire, raises one finger, and tilts their head as though listening."] = "se penche vers le feu, lève un doigt, et incline la tête comme pour écouter.",
	["leans toward the fire."] = "se penche vers le feu.",
	["leans toward the firelight, as if about to share a secret."] = "se penche vers la lueur du feu, comme pour confier un secret.",
	["leans toward {target} with great seriousness, hands folded."] = "se penche vers {target} avec un grand sérieux, les mains jointes.",
	["lets a long silence go by, watching the smoke above the flames."] = "laisse passer un long silence, les yeux sur la fumée au-dessus des flammes.",
	["lets go of the levers and raises both hands, grinning."] = "lâche les leviers et lève les deux mains, un grand sourire aux lèvres.",
	["lets go of their own sleeves and settles both hands in their lap."] = "lâche ses propres manches et pose les deux mains sur ses genoux.",
	["lets one hand hang low at their side, fingers moving as if scratching an ear."] = "laisse pendre une main le long du corps, les doigts remuant comme pour gratter une oreille.",
	["lets one hand hang low, palm open, and leaves it there."] = "laisse pendre une main, paume ouverte, et ne la bouge plus.",
	["lets the fire tick and settle for a while before going on."] = "laisse le feu crépiter et se tasser un moment avant de reprendre.",
	["lets the silence sit a moment before saying anything else."] = "laisse le silence s'installer un moment avant de reprendre la parole.",
	["lets the silence sit so long that a log settling in the fire sounds loud."] = "laisse le silence s'installer si longtemps qu'une bûche qui s'affaisse dans le feu semble faire un vacarme.",
	["lets their eyes drift past the firelight into the dark, and keeps them there a little too long."] = "laisse son regard glisser au-delà du feu, dans le noir, et l'y garde un peu trop longtemps.",
	["licks a fingertip, holds it up gravely, and nods as if it has told them something important."] = "se lèche le bout du doigt, le lève gravement, et hoche la tête comme s'il venait de lui apprendre quelque chose d'important.",
	["lifts a cup carefully in both hands, then sniffs it."] = "soulève une coupe avec précaution, à deux mains, puis la renifle.",
	["lifts a hand in a small wave."] = "lève une main en un petit signe.",
	["lifts a wet finger into the air, holds it there, and slowly lowers it."] = "lève un doigt mouillé en l'air, le garde là, puis l'abaisse lentement.",
	["lifts an invisible cup, blows across it, and sips with great care."] = "lève une tasse invisible, souffle dessus et en boit une gorgée avec grand soin.",
	["lifts an invisible heavy sack to shoulder height and holds it there, waiting."] = "soulève un lourd sac invisible à hauteur d'épaule et le tient là, en attendant.",
	["lifts an unseen plate and wipes it, very gently, with their sleeve."] = "soulève une assiette invisible et l'essuie, tout doucement, avec sa manche.",
	["lifts one finger and gives a tiny invisible bell a single tap."] = "lève un doigt et tapote une seule fois une minuscule clochette invisible.",
	["lifts one fist and brings it down sharply, as if striking with a hammer of light."] = "lève un poing et l'abat d'un coup sec, comme pour frapper avec un marteau de lumière.",
	["lifts one hand and studies the shadow it casts, turning it slowly."] = "lève une main et étudie l'ombre qu'elle projette, en la tournant lentement.",
	["lifts one hand slowly, as if stepping over something, then lets it settle."] = "lève lentement une main, comme pour enjamber quelque chose, puis la laisse se poser.",
	["lifts the lid of an invisible box, very slowly."] = "soulève très lentement le couvercle d'une boîte invisible.",
	["lifts the stone to their ear and goes quiet."] = "porte la pierre à son oreille et se tait.",
	["lifts their chin and answers softly to no one, \"Here.\""] = "lève le menton et répond doucement, à personne : « Je suis là. »",
	["lifts their chin and looks down their nose, cold as a winter morning."] = "lève le menton et toise tout le monde de haut, avec la froideur d'un matin d'hiver.",
	["lifts their chin and sniffs at the air, then wishes they hadn't."] = "lève le menton et renifle l'air, puis le regrette aussitôt.",
	["lifts their hand off the ground beside the fire, slowly, and listens."] = "soulève lentement sa main du sol, près du feu, et tend l'oreille.",
	["linen cloth"] = "de l'étoffe de lin",
	["links their fingers together, then pulls hard with both arms."] = "entrelace ses doigts, puis tire fort des deux bras.",
	["listens to the fire tick and pop, counting under their breath, then stops."] = "écoute le feu craquer et crépiter en comptant à mi-voix, puis s'arrête.",
	["looks above the firelight for a long, quiet moment."] = "lève les yeux au-delà de la lueur du feu, un long moment, en silence.",
	["looks around at an unseen slope and gives a small, tired shrug."] = "balaie du regard une pente invisible et hausse doucement les épaules, avec lassitude.",
	["looks around the circle and lets the question hang, one eyebrow up."] = "fait le tour du cercle des yeux et laisse la question en suspens, un sourcil levé.",
	["looks around the circle and nods once at each listener, as if daring one of them to ask."] = "fait le tour du cercle du regard et adresse un seul hochement de tête à chacun, comme pour défier quiconque de poser la question.",
	["looks around the circle with raised eyebrows, waiting for someone to ask."] = "regarde le cercle, sourcils levés, en attendant que quelqu'un pose la question.",
	["looks around the circle, daring someone to ask the obvious question."] = "parcourt le cercle du regard, comme pour mettre quelqu'un au défi de poser la question qui s'impose.",
	["looks at the ground near {target} and goes quiet."] = "regarde le sol près de {target} et se tait.",
	["looks at the log in their hand, and sets it down beside the fire instead of on it."] = "regarde la bûche dans sa main, et la pose à côté du feu plutôt que dedans.",
	["looks at their empty hands, then follows something slow along the ground with their eyes."] = "regarde ses mains vides, puis suit des yeux quelque chose de lent sur le sol.",
	["looks at their hands, then slowly folds them out of sight."] = "regarde ses mains, puis les replie lentement pour les cacher.",
	["looks at their open hand for a moment, then closes it gently."] = "regarde un instant sa main ouverte, puis la referme doucement.",
	["looks at {target} across the flames for a little too long, then looks away."] = "regarde {target} par-dessus les flammes un peu trop longtemps, puis détourne les yeux.",
	["looks at {target}, then back into the fire."] = "regarde {target}, puis de nouveau le feu.",
	["looks away and runs a thumb slowly along the edge of their sleeve."] = "détourne le regard et passe lentement le pouce le long de sa manche.",
	["looks down at the coals."] = "baisse les yeux vers les braises.",
	["looks down at the fire, then at the ground beneath it, and nudges a stray coal back into the ring."] = "baisse les yeux sur le feu, puis sur le sol en dessous, et repousse dans le cercle une braise égarée.",
	["looks down at their boots, not sure how to go on."] = "baisse les yeux vers ses bottes, sans trop savoir comment continuer.",
	["looks down at their hands and slowly opens them."] = "baisse les yeux sur ses mains et les ouvre lentement.",
	["looks down at their hands, working at an invisible length of rope."] = "baisse les yeux sur ses mains, qui s'affairent sur une corde invisible.",
	["looks down at their own boot, and holds very still."] = "baisse les yeux sur sa propre botte, et ne bouge plus du tout.",
	["looks down at their own hands and turns them over slowly."] = "baisse les yeux sur ses mains et les retourne lentement.",
	["looks down at their wrist and gives it a small, testing shake."] = "baisse les yeux sur son poignet et le secoue un peu, pour voir.",
	["looks down fondly at a spot near their feet."] = "pose un regard tendre sur un coin du sol, près de ses pieds.",
	["looks down into their cup for a moment, smiling a little."] = "baisse les yeux vers sa tasse un moment, avec un petit sourire.",
	["looks down, startled, and slowly lowers one raised arm."] = "sursaute, découvre son bras levé, et l'abaisse lentement.",
	["looks from one side to the other, slowly, and then back again."] = "regarde d'un côté, puis de l'autre, lentement, et revient au premier.",
	["looks into the fire for a long moment, then nods once."] = "fixe le feu un long moment, puis hoche la tête une fois.",
	["looks into the fire."] = "regarde le feu.",
	["looks off into the dark beyond the circle, jaw tight."] = "regarde au loin dans le noir, au-delà du cercle, la mâchoire serrée.",
	["looks off into the dark, as if counting distant campfires."] = "regarde au loin dans le noir, comme pour compter des feux de camp lointains.",
	["looks off into the distance, as if over still water, and goes quiet for a moment."] = "regarde au loin, comme au-dessus d'une eau immobile, et se tait un moment.",
	["looks out at some high, distant point and takes a slow breath."] = "regarde au loin un point haut et lointain, et prend une lente inspiration.",
	["looks out over the heads of the circle, as if at a far-off valley."] = "regarde par-dessus les têtes du cercle, comme vers une vallée lointaine.",
	["looks past the firelight at the black trees, and very carefully does not answer them."] = "regarde au-delà du feu les arbres noirs, et se garde bien de leur répondre.",
	["looks skyward and slowly hunches their shoulders, as if something were circling."] = "regarde vers le ciel et rentre lentement les épaules, comme si quelque chose tournoyait là-haut.",
	["looks slowly around the circle, at each face the firelight reaches, and then away."] = "parcourt lentement le cercle du regard, visage après visage, aussi loin que porte la lueur du feu, puis détourne les yeux.",
	["looks slowly around the circle, lips moving as if counting."] = "fait lentement le tour du cercle des yeux, les lèvres remuant comme pour compter.",
	["looks slowly down at their own hands, and draws them in close to the fire."] = "baisse lentement les yeux sur ses mains, et les ramène tout près du feu.",
	["looks slowly to either side, searching, then lowers their gaze."] = "regarde lentement de chaque côté, cherche quelque chose, puis baisse les yeux.",
	["looks slowly upward, then back down at the ground by their feet."] = "lève lentement les yeux, puis les ramène au sol, à ses pieds.",
	["looks up at the moon."] = "lève les yeux vers la lune.",
	["looks up at the sky."] = "lève les yeux vers le ciel.",
	["looks up slowly, then down at their own feet, frowning."] = "lève lentement les yeux, puis les baisse vers ses pieds, les sourcils froncés.",
	["looks up toward the mountains."] = "lève les yeux vers les montagnes.",
	["looks {target} up and down, counting something on their fingers."] = "toise {target} de haut en bas, en comptant quelque chose sur ses doigts.",
	["lowers a bow and breathes out slowly."] = "abaisse un arc et souffle lentement.",
	["lowers an invisible lantern slowly, then stops short and pulls it back."] = "abaisse lentement une lanterne invisible, puis s'arrête net et la retire vivement.",
	["lowers the invisible spoon and shakes their head slowly."] = "abaisse la cuillère invisible et secoue lentement la tête.",
	["lowers their gaze and walks two fingers slowly along one knee, as if following something along the ground."] = "baisse le regard et fait lentement marcher deux doigts le long d'un genou, comme pour suivre une piste au sol.",
	["lowers their head and rests both hands on their weapon."] = "baisse la tête et pose les deux mains sur son arme.",
	["lowers their head and sinks their shoulders slowly, like something going under."] = "baisse la tête et laisse ses épaules s'affaisser lentement, comme quelque chose qui sombre.",
	["lowers their voice and glances over one shoulder at nobody."] = "baisse la voix et jette un coup d'œil par-dessus son épaule, alors qu'il n'y a personne.",
	["lowers their voice."] = "baisse la voix.",
	["lunges forward and snaps one hand shut, then hauls it back."] = "se jette en avant, referme une main d'un coup sec, puis la ramène de toutes ses forces.",
	["makes a small gurgling noise, then looks embarrassed."] = "pousse un petit gargouillis, puis prend un air gêné.",
	["makes a small, courteous bow, then another, then catches themselves halfway through a third."] = "fait une petite révérence courtoise, puis une autre, puis s'interrompt au beau milieu d'une troisième.",
	["mimes a short, patient tap against the ground, over and over."] = "mime un petit coup patient contre le sol, encore et encore.",
	["mimes lifting the lid of a heavy chest, then lets their shoulders drop."] = "mime le geste de soulever le couvercle d'un lourd coffre, puis laisse retomber ses épaules.",
	["mimes peeling something wet from their sleeve, with growing disgust."] = "mime le geste de décoller quelque chose de mouillé de sa manche, avec un dégoût croissant.",
	["mimes reaching down, lifting, and setting something gently on the ground."] = "mime le geste de se pencher, de soulever quelque chose et de le poser doucement par terre.",
	["mimes shaping a snowball between their palms and gives one short, hopeless throw."] = "façonne une boule de neige entre ses paumes et la lance mollement, sans le moindre espoir.",
	["mouths a word carefully and silently, as if practicing it."] = "articule un mot avec soin, en silence, comme pour s'entraîner.",
	["moves one hand as if brushing through hanging leaves."] = "balaie l'air d'une main, comme pour écarter un rideau de feuilles.",
	["moves one hand forward, stops it suddenly, and waits with their head on one side."] = "avance une main, l'arrête net et attend, la tête penchée.",
	["moves their lips silently for a moment, eyes closed."] = "remue les lèvres en silence un moment, les yeux fermés.",
	["narrows their eyes and leans closer to something invisible, then draws back sharply."] = "plisse les yeux et se penche vers quelque chose d'invisible, puis recule brusquement.",
	["narrows their eyes and shifts their weight, as if sizing someone up."] = "plisse les yeux et déplace son poids, comme pour jauger quelqu'un.",
	["narrows their eyes at {target}, then slowly grins."] = "plisse les yeux en regardant {target}, puis sourit lentement.",
	["narrows their eyes, as though at some small and hated foe."] = "plisse les yeux, comme devant un petit ennemi juré.",
	["nods at the fire and shows their tusks in a wide, lazy grin."] = "désigne le feu d'un signe de tête et montre ses défenses en un large sourire paresseux.",
	["nods once, as if that's the end of the matter."] = "hoche la tête une fois, comme si l'affaire était close.",
	["nods slowly and approvingly, as if at a fine piece of work."] = "hoche lentement la tête d'un air approbateur, comme devant du bel ouvrage.",
	["nods solemnly at {target}."] = "adresse à {target} un hochement de tête solennel.",
	["nods to {target} and settles back."] = "adresse un signe de tête à {target} et se cale en arrière.",
	["nudges a log deeper into the coals."] = "pousse une bûche plus loin dans les braises.",
	["opens a pack, reaches in, and pulls their hand back quickly."] = "ouvre un sac, y plonge la main et la retire vivement.",
	["opens one hand and studies the middle of the palm in the firelight."] = "ouvre une main et examine le creux de la paume à la lueur du feu.",
	["opens one hand slowly and looks at what would be lying in it."] = "ouvre lentement une main et regarde ce qui pourrait y reposer.",
	["opens one hand to reveal a small, dark seed, worn smooth with handling."] = "ouvre une main sur une petite graine sombre, polie à force d'être maniée.",
	["opens their mouth to answer, then thoughtfully closes it."] = "ouvre la bouche pour répondre, puis la referme, pensivement.",
	["opens their mouth to speak, then closes it and looks down at their hands."] = "ouvre la bouche pour parler, puis la referme et baisse les yeux sur ses mains.",
	["passes something heavy from one hand to the other, again and again, quickly."] = "fait passer quelque chose de lourd d'une main à l'autre, encore et encore, très vite.",
	["pats a small pouch at their belt, and lets their hand stay there."] = "tapote une petite bourse à sa ceinture, et y laisse la main.",
	["pats an invisible pack at their side."] = "tapote un sac invisible à son côté.",
	["pats the air at shoulder height, as if feeling for something worn."] = "tâte l'air à hauteur d'épaule, comme pour retrouver un creux poli par l'usage.",
	["pats the empty ground beside them."] = "tapote le sol vide, juste à côté.",
	["pats the ground beside them as if greeting an old friend, nodding slowly."] = "tapote le sol à ses côtés, comme pour saluer un vieil ami, en hochant lentement la tête.",
	["pats their own face and arms, as if checking they're all still there."] = "se palpe le visage et les bras, comme pour vérifier que tout est encore là.",
	["pats their pack gently."] = "tapote doucement son sac.",
	["pats their pockets, then turns one inside out."] = "tâte ses poches, puis en retourne une.",
	["pats their stomach slowly with one hand, looking wounded."] = "se tapote lentement le ventre d'une main, l'air blessé.",
	["pats their stomach, then holds up one finger as though something has just occurred to them."] = "se tapote le ventre, puis lève un doigt, comme si une idée venait de surgir.",
	["pats their thigh twice, softly, and looks down."] = "se tapote deux fois la cuisse, doucement, et baisse les yeux.",
	["pauses with an imaginary spoon halfway to their mouth."] = "s'arrête, une cuillère imaginaire à mi-chemin de la bouche.",
	["pauses with an invisible spoon halfway to their mouth, then slowly lowers it."] = "s'arrête, une cuillère invisible à mi-chemin de la bouche, puis la repose lentement.",
	["pauses, and raises a hand as if holding up a lantern."] = "marque une pause et lève une main, comme pour tenir une lanterne.",
	["peacebloom"] = "de la pacifique",
	["peels back a blanket and peers in, without any sudden movements."] = "soulève un pan de couverture et jette un œil dessous, sans le moindre geste brusque.",
	["peels something sticky off their sleeve, and then has trouble getting it off their fingers."] = "décolle quelque chose de collant de sa manche, puis n'arrive plus à le décoller de ses doigts.",
	["peers at the ground near {target}, watching how the firelight falls."] = "scrute le sol près de {target}, en observant comment tombe la lumière du feu.",
	["peers between their fingers, as if through leaves, at something far off."] = "regarde entre ses doigts, comme à travers des feuilles, quelque chose au loin.",
	["peers down into cupped hands, searching for something small."] = "scrute le creux de ses mains, à la recherche de quelque chose de minuscule.",
	["peers into a bowl, then gives it a polite nod."] = "scrute le fond d'un bol, puis lui adresse un petit signe de tête poli.",
	["peers off toward the hills, chewing slowly."] = "scrute les collines au loin, en mâchant lentement.",
	["peers over an imaginary edge and slowly draws back, swallowing."] = "se penche au-dessus d'un vide imaginaire et recule lentement, en déglutissant.",
	["peers suspiciously into an imaginary bowl and stirs it with one finger."] = "scrute d'un air méfiant un bol imaginaire et le remue du doigt.",
	["picks a twig from the kindling, considers how long it took to grow, and feeds it to the fire anyway."] = "prend une brindille dans le petit bois, songe au temps qu'il lui a fallu pour pousser, et la jette au feu quand même.",
	["picks an invisible crumb from their own chin, and studies it."] = "retire une miette invisible de son menton et l'examine.",
	["picks an invisible lock with two fingers, then freezes with their head cocked."] = "crochète une serrure invisible de deux doigts, puis se fige, la tête inclinée.",
	["picks at an invisible knot with blunt, patient fingers."] = "tripote un nœud invisible avec des doigts épais et patients.",
	["picks at an invisible knot with their fingertips, frowning."] = "tripote un nœud invisible du bout des doigts, les sourcils froncés.",
	["pinches an invisible line between two fingers and lets it droop slowly."] = "pince une corde invisible entre deux doigts et la laisse lentement s'affaisser.",
	["pinches an invisible needle and draws a slow thread through the air."] = "pince une aiguille invisible et tire lentement un fil dans l'air.",
	["pinches an invisible thread and lifts it carefully clear of something below."] = "pince un fil invisible et le soulève avec précaution au-dessus de quelque chose.",
	["pitches forward with arms spread wide, then jerks upward as if yanked by the collar."] = "bascule en avant, les bras grands ouverts, puis se redresse d'un coup, comme si on l'attrapait par le col.",
	["plants both hands flat on their knees and sets their shoulders, immovable."] = "pose les deux mains à plat sur les genoux et carre les épaules, inébranlable.",
	["plants their fists on their hips and glares at the ground, jaw thrust forward."] = "plante ses poings sur ses hanches et foudroie le sol du regard, la mâchoire en avant.",
	["plants their hands on their hips and looks up, like someone addressing a stubborn child."] = "pose les poings sur les hanches et lève les yeux, comme pour sermonner un enfant têtu.",
	["plants their hands on their hips and surveys a vast and empty view."] = "plante les poings sur les hanches et contemple un panorama immense et vide.",
	["points around in a slow circle, lips moving silently."] = "pointe le doigt tout autour, lentement, en remuant les lèvres sans un son.",
	["points at two spots on their open palm, one and then the other."] = "désigne deux endroits au creux de sa main ouverte, l'un après l'autre.",
	["points left with one hand, right with the other, and then tries to point up with an elbow."] = "montre la gauche d'une main, la droite de l'autre, puis essaie d'indiquer le ciel avec un coude.",
	["points left, then right, then gives their own hand a puzzled look."] = "montre la gauche, puis la droite, puis regarde sa propre main d'un air perplexe.",
	["points north with a stick from the fire."] = "montre le nord avec un bâton tiré du feu.",
	["points once toward the fire ring, pauses, and lowers their hand without finishing the count."] = "pointe une fois le doigt vers le cercle de pierres du feu, hésite, et baisse la main sans finir de compter.",
	["points slowly around the circle where they sit, at nothing in particular."] = "promène lentement le doigt tout autour du cercle, sans rien désigner de précis.",
	["pokes a stick into the coals and considers it gravely."] = "enfonce un bâton dans les braises et l'examine gravement.",
	["pokes at the fire and watches the sparks climb."] = "tisonne le feu et regarde les étincelles monter.",
	["pokes the fire and watches the sparks climb."] = "tisonne le feu et regarde les étincelles monter.",
	["pokes the fire twice and clears their throat, a little too loudly."] = "tisonne deux fois le feu et s'éclaircit la gorge, un peu trop fort.",
	["pokes the fire until it crackles, then looks around the circle."] = "tisonne le feu jusqu'à ce qu'il crépite, puis balaie le cercle du regard.",
	["pokes their tongue into their cheek and winces."] = "appuie la langue contre sa joue et grimace.",
	["pops something imaginary into their mouth and chews happily."] = "gobe quelque chose d'imaginaire et mâche avec bonheur.",
	["pounds out a rhythm on their thigh that falls apart almost at once."] = "martèle sur sa cuisse un rythme qui s'effondre presque aussitôt.",
	["presses a hand flat over their heart and lets out a long breath."] = "pose une main à plat sur son cœur et pousse un long soupir.",
	["presses a palm flat against their chest, then lets it fall."] = "presse une paume à plat contre sa poitrine, puis la laisse retomber.",
	["presses an ear to an unseen pipe and holds their breath."] = "colle l'oreille contre un tuyau invisible et retient son souffle.",
	["presses one finger to their lips and looks up, not moving at all."] = "pose un doigt sur ses lèvres et lève les yeux, sans bouger le moindre muscle.",
	["presses one palm against the empty air and slowly draws it back."] = "appuie une paume contre le vide, puis la retire lentement.",
	["presses one thumb gently into the center of their other palm."] = "presse doucement un pouce au creux de son autre paume.",
	["presses their lips together and gives a small, stiff nod."] = "pince les lèvres et fait un petit signe de tête, un peu raide.",
	["presses their thumb into the palm of their other hand and holds it there."] = "appuie le pouce au creux de l'autre main et l'y laisse un long moment.",
	["pretends to gallop with both hands."] = "fait mine de galoper avec les deux mains.",
	["pretends to pour something from nothing."] = "fait mine de verser quelque chose venu de nulle part.",
	["prods a charred log with a stick, twice, just to be sure."] = "tâte deux fois une bûche calcinée du bout d'un bâton, par acquit de conscience.",
	["puckers their mouth and swallows hard at the memory."] = "fait la moue et déglutit péniblement à ce souvenir.",
	["puffs out their cheeks and frowns up at the sky."] = "gonfle les joues et fronce les sourcils vers le ciel.",
	["puffs out their chest proudly, then lets it sag."] = "bombe fièrement le torse, puis le laisse retomber.",
	["puffs up their chest."] = "bombe le torse.",
	["pulls a knot tight in an invisible rope, and keeps both hands on it."] = "serre un nœud sur une corde invisible, et garde les deux mains dessus.",
	["pulls a loose thread from their sleeve and drops it in the flames without a word."] = "tire un fil qui dépasse de sa manche et le laisse tomber dans les flammes sans un mot.",
	["pulls a loose thread from their sleeve and lets the updraft off the fire carry it away."] = "tire un fil de sa manche et laisse l'air chaud du feu l'emporter.",
	["pulls a small feather from nowhere and smooths it between their fingers."] = "sort une petite plume de nulle part et la lisse entre ses doigts.",
	["pulls a worn spoon from their belt and gives it a little flourish."] = "tire une cuillère usée de sa ceinture et la fait tournoyer avec panache.",
	["pulls an invisible folded letter from a pocket and frowns at it, then at {target}."] = "sort de sa poche une lettre pliée invisible, la regarde en fronçant les sourcils, puis regarde {target}.",
	["pulls at something around their neck, and holds the end up to look at it."] = "tire sur quelque chose autour de son cou, et en lève le bout pour le regarder.",
	["pulls off an invisible coat, throws it over something, then tugs gently on a lead."] = "retire un manteau invisible, le jette sur quelque chose, puis tire doucement sur une longe.",
	["pulls on one invisible glove, then another over it, flexing their fingers."] = "enfile un gant invisible, puis un autre par-dessus, en remuant les doigts.",
	["pulls slowly on an invisible rope, then again, keeping time."] = "tire lentement sur une corde invisible, puis encore, en gardant la cadence.",
	["pulls their coat closed and turns their face out of the firelight."] = "referme son manteau et détourne le visage de la lueur du feu.",
	["pulls their hand back from the fire quickly."] = "retire vivement la main du feu.",
	["pumps their arms, breathing hard, and glances back over one shoulder."] = "mouline des bras, le souffle court, et jette un coup d'œil par-dessus l'épaule.",
	["pumps their elbows where they sit, breathing hard."] = "joue des coudes sans se lever, comme en pleine course, le souffle court.",
	["purses their lips and whistles two soft notes, up and down."] = "pince les lèvres et siffle deux notes douces, une haute, une basse.",
	["pushes their pack an arm's length away, hesitates, and draws it close again."] = "repousse son sac à bout de bras, hésite, puis le ramène tout près.",
	["raises a cup to no one in particular."] = "lève sa tasse à la santé de personne en particulier.",
	["raises a finger toward the dark overhead, then lets it sink."] = "lève un doigt vers le noir du ciel, puis le laisse retomber.",
	["raises a fist and brings it down slowly, as if on an unseen anvil."] = "lève un poing et l'abat lentement, comme sur une enclume invisible.",
	["raises a hand flat above their own head, as if measuring."] = "lève une main à plat au-dessus de sa tête, comme pour se mesurer.",
	["raises an eyebrow and gives the fire a slow, knowing look."] = "hausse un sourcil et lance au feu un long regard entendu.",
	["raises an imaginary mug toward the fire."] = "lève une chope imaginaire vers le feu.",
	["raises an imaginary spear, sights down it, then shifts their aim a little low."] = "lève une lance imaginaire, vise le long du manche, puis abaisse un peu son tir.",
	["raises an invisible bucket a little way, holds it there, and then sets it down again."] = "soulève un peu un seau invisible, le garde ainsi un instant, puis le repose.",
	["raises an invisible vial to the firelight."] = "lève une fiole invisible à la lueur du feu.",
	["raises an unsteady hand and sways where they sit, squinting along an invisible blade."] = "lève une main tremblante et tangue sur place, en plissant les yeux le long d'une lame invisible.",
	["raises both arms and sways solemnly from side to side."] = "lève les deux bras et se balance gravement d'un côté à l'autre.",
	["raises both fists and brings them down hard on an invisible drum, once, twice."] = "lève les deux poings et les abat violemment sur un tambour invisible, une fois, deux fois.",
	["raises both fists as if gripping a hilt and braces against the air."] = "lève les deux poings comme pour empoigner une épée, et s'arc-boute contre le vide.",
	["raises both hands as if gripping an axe, then brings them down hard."] = "lève les deux mains comme pour empoigner une hache, puis les abat d'un coup.",
	["raises both hands solemnly, then winces at the memory."] = "lève solennellement les deux mains, puis grimace au souvenir.",
	["raises both palms, as if calming two arguing friends."] = "lève les deux paumes, comme pour calmer deux amis en pleine dispute.",
	["raises one arm overhead at an angle, bracing it with the other hand, and winces at each blow."] = "lève un bras au-dessus de la tête, en biais, le soutient de l'autre main, et grimace à chaque choc.",
	["raises one finger to explain, thinks better of it, and lowers it slowly."] = "lève un doigt pour expliquer, se ravise, et le baisse lentement.",
	["raises one hand near the fire and studies the shadow between their fingers."] = "lève une main près du feu et observe l'ombre entre ses doigts.",
	["raises one hand solemnly, as if casting a vote."] = "lève solennellement une main, comme pour voter.",
	["raises one open hand quickly, fingers spread, and holds it there."] = "lève vivement une main ouverte, doigts écartés, et la garde en l'air.",
	["raises their cup, solemnly, as if to a worthy opponent."] = "lève solennellement sa tasse, comme à la santé d'un adversaire digne de ce nom.",
	["rakes the coals together with a stick, saving the heat."] = "rassemble les braises avec un bâton, pour garder la chaleur.",
	["raps their knuckles three times on the ground, then waits."] = "toque trois fois contre le sol, puis attend.",
	["raps three times on the ground beside them, then waits, head tilted."] = "frappe trois fois le sol à ses côtés, puis attend, la tête penchée.",
	["reaches out and gently smooths a strand of invisible hair."] = "tend la main et lisse doucement une mèche de cheveux invisible.",
	["reaches up and carefully snips at something overhead with two fingers."] = "lève les bras et coupe délicatement quelque chose au-dessus de sa tête, avec deux doigts.",
	["reaches up, hand over hand, breathing harder with every reach."] = "tend les bras vers le haut, une main après l'autre, le souffle de plus en plus court.",
	["rests a hand flat on their knee and looks into the coals for a while."] = "pose une main à plat sur son genou et regarde les braises un long moment.",
	["rests a hand on an invisible neck and pats it twice."] = "pose la main sur une encolure invisible et la tapote deux fois.",
	["rests one hand on the air, as if on the top of a low gate, then lets it fall."] = "pose une main dans le vide, comme sur le haut d'une barrière basse, puis la laisse retomber.",
	["rests their fingertips lightly over one pocket."] = "pose légèrement le bout des doigts sur une poche.",
	["rolls one shoulder, as if the bruise still aches."] = "fait rouler une épaule, comme si le bleu lui faisait encore mal.",
	["rolls something small between finger and thumb, then flicks it away."] = "fait rouler quelque chose de minuscule entre le pouce et l'index, puis l'envoie d'une pichenette.",
	["rolls their neck and stretches, in a distinctly animal way."] = "fait rouler sa tête et s'étire, avec quelque chose de franchement animal.",
	["rolls their shoulders, then tilts slowly into some unfelt gust."] = "roule des épaules, puis s'incline lentement dans une rafale que personne ne sent.",
	["rolls up one sleeve to show an old, crescent-shaped scar."] = "remonte une manche et montre une vieille cicatrice en forme de croissant.",
	["rubs a pinch of cold ash from the fire's edge between their fingers, and smiles."] = "frotte entre ses doigts une pincée de cendre froide prise au bord du feu, et sourit.",
	["rubs a pinch of cold ash from the fire's edge between their fingers, with some satisfaction."] = "frotte entre ses doigts une pincée de cendre froide prise au bord du feu, avec une certaine satisfaction.",
	["rubs a thumb across their own palm, as if the handshake were still there."] = "se frotte la paume du pouce, comme si la poignée de main y était encore.",
	["rubs a thumb across their palm, as if wiping dirt off something small."] = "se frotte la paume du pouce, comme pour essuyer la terre de quelque chose de petit.",
	["rubs a thumb and two fingers together."] = "frotte le pouce contre deux doigts.",
	["rubs a thumb in small, firm circles over one palm."] = "frotte le pouce en petits cercles fermes sur une paume.",
	["rubs an invisible coin between finger and thumb."] = "frotte une pièce invisible entre le pouce et l'index.",
	["rubs both wrists slowly, as if feeling old chains."] = "se frotte lentement les poignets, comme pour y sentir encore de vieilles chaînes.",
	["rubs finger and thumb together as though testing a pinch of grit."] = "frotte le pouce contre l'index, comme pour éprouver une pincée de sable.",
	["rubs finger and thumb together, as though testing a pinch of soil."] = "frotte le pouce contre l'index, comme pour éprouver une pincée de terre.",
	["rubs the back of their neck, and looks down at the fire."] = "se frotte la nuque et baisse les yeux vers le feu.",
	["rubs the back of their neck, sheepish."] = "se frotte la nuque, l'air penaud.",
	["rubs the side of one thumb slowly across their palm."] = "passe lentement le côté du pouce sur sa paume.",
	["rubs their fingers together, as if brushing away soot."] = "se frotte les doigts, comme pour en chasser la suie.",
	["rubs their hands together by the fire."] = "se frotte les mains près du feu.",
	["rubs their thumb and fingers together as though testing for dust, then stops themselves."] = "frotte le pouce contre les doigts comme pour tâter de la poussière, puis s'arrête net.",
	["runs a finger slowly down an invisible page, then stops."] = "fait lentement glisser un doigt le long d'une page invisible, puis s'arrête.",
	["runs a fingertip along an imaginary seam on their sleeve."] = "suit du doigt une couture imaginaire sur sa manche.",
	["runs a hand low through the air, near the knee, as if along an old wall."] = "promène une main dans l'air, à hauteur de genou, comme le long d'un vieux mur.",
	["runs a length of old cord through their fingers, stopping at each knot."] = "fait glisser une vieille cordelette entre ses doigts, en s'arrêtant à chaque nœud.",
	["runs a slow hand along an invisible length of wood, feeling for the grain."] = "passe lentement la main le long d'une pièce de bois invisible, pour en sentir le fil.",
	["runs a thumb along an invisible edge."] = "passe le pouce le long d'un fil invisible.",
	["runs a thumb along an old notch in their weapon."] = "passe le pouce sur une vieille entaille de son arme.",
	["runs a thumb along the nicks in their blade."] = "passe le pouce le long des brèches de sa lame.",
	["runs a thumb over a board, then stops at something and looks closer."] = "passe le pouce sur une planche, puis s'arrête sur quelque chose et regarde de plus près.",
	["runs one finger down an invisible page, then stops."] = "fait glisser un doigt le long d'une page invisible, puis s'arrête.",
	["says nothing more, and watches the black branches lean a little closer over the firelight."] = "n'ajoute rien, et regarde les branches noires se pencher un peu plus au-dessus de la lueur du feu.",
	["scoops up a handful of dirt and lets it sift through their fingers."] = "ramasse une poignée de terre et la laisse filer entre ses doigts.",
	["scoops up a handful of imaginary dirt, frowns at it, and lets it run through their fingers."] = "ramasse une poignée de terre imaginaire, la regarde en fronçant les sourcils et la laisse filer entre ses doigts.",
	["scratches a slow line in the ashes with a stick, then adds another beneath it."] = "trace lentement un trait dans les cendres avec un bâton, puis en ajoute un autre en dessous.",
	["scratches an imaginary companion behind the ears."] = "gratte un compagnon imaginaire derrière les oreilles.",
	["scuttles two fingers along an imaginary track, grinning wide."] = "fait trotter deux doigts le long d'une piste imaginaire, avec un grand sourire.",
	["sets a scrap of jerky down beside them, where an old dog might find it."] = "pose un bout de viande séchée juste à côté, là où un vieux chien pourrait le trouver.",
	["sets a scrap of their dinner at the edge of the firelight, and does not look to see what comes."] = "pose un bout de son dîner au bord de la lumière du feu, et ne regarde pas ce qui vient le prendre.",
	["sets a small stone on the ring around the fire, then a second beside it, and says no more."] = "pose une petite pierre sur le cercle autour du feu, puis une seconde à côté, et n'ajoute rien.",
	["sets one shoulder low and pushes slowly forward, jaw tight."] = "baisse une épaule et pousse lentement vers l'avant, la mâchoire serrée.",
	["sets one thing on top of another, with great care, and sits back."] = "pose une chose sur une autre, avec grand soin, et se redresse.",
	["sets something down with both hands and does not look up."] = "pose quelque chose à deux mains et ne relève pas les yeux.",
	["sets something heavy down carefully and eases themselves back with a long breath."] = "pose avec précaution quelque chose de lourd et se laisse aller en arrière avec un long soupir.",
	["sets the stick down and nods across the flames at {target}."] = "repose le bâton et adresse un signe de tête à {target} par-dessus les flammes.",
	["sets the stone by the ring of the fire, carefully, as if leaving it for someone."] = "pose le caillou au bord du cercle de pierres, avec soin, comme pour le laisser à quelqu'un.",
	["sets their two fists side by side, then opens a small gap between them."] = "pose ses deux poings côte à côte, puis les écarte un tout petit peu.",
	["settles lower, as though easing onto the edge of a cot."] = "se tasse un peu, comme pour s'asseoir doucement au bord d'un lit de camp.",
	["settles their weight with a grunt and starts unlacing an imaginary boot with great care."] = "s'installe avec un grognement et commence à délacer avec grand soin une botte imaginaire.",
	["shades their eyes and cranes their neck, squinting past the firelight."] = "s'abrite les yeux de la main et tend le cou, en scrutant au-delà de la lueur du feu.",
	["shades their eyes and peers around the circle of listeners, looking increasingly worried."] = "met sa main en visière et scrute le cercle, l'air de plus en plus inquiet.",
	["shades their eyes with one hand and peers around the fire."] = "met une main en visière et scrute les alentours du feu.",
	["shakes a fist at the sky, then stops to catch their breath."] = "menace le ciel du poing, puis s'arrête pour reprendre son souffle.",
	["shakes a fist in the air as if ringing a bell, faster and faster."] = "agite le poing en l'air comme pour sonner une cloche, de plus en plus vite.",
	["shapes a small tin in the air with both hands, then gently closes the lid."] = "façonne une petite boîte dans l'air des deux mains, puis en referme doucement le couvercle.",
	["shaves a thin curl from a small piece of wood and watches it fall."] = "détache un fin copeau d'un petit morceau de bois et le regarde tomber.",
	["shields a tiny flame with one hand."] = "protège une minuscule flamme d'une main.",
	["shifts an invisible weight on one shoulder and rubs the spot with a grimace."] = "rajuste un poids invisible sur son épaule et se frotte l'endroit en grimaçant.",
	["shifts back against nothing at all and slowly, blissfully, rubs their back from side to side."] = "se cale contre le vide et, lentement, avec béatitude, se frotte le dos de droite à gauche.",
	["shifts over a little, leaving space by the fire as if for someone else."] = "se décale un peu et laisse une place près du feu, comme pour quelqu'un d'autre.",
	["shifts over to one side, leaving a space beside them."] = "se décale un peu, et laisse une place libre à côté.",
	["shivers and pulls their cloak a little tighter."] = "frissonne et resserre un peu sa cape.",
	["shoves at the air with both hands, wincing with each push."] = "pousse l'air des deux mains, en grimaçant à chaque poussée.",
	["shoves both hands sideways through the air, hard."] = "pousse violemment les deux mains sur le côté.",
	["shoves hard at the air with both hands."] = "pousse violemment l'air des deux mains.",
	["shoves something round forward with both hands, then grips the air tight."] = "pousse à deux mains quelque chose de rond, puis s'agrippe au vide de toutes ses forces.",
	["sighs and shakes their head at the fire."] = "soupire et secoue la tête devant le feu.",
	["sighs."] = "soupire.",
	["sinks down slowly until their chin is tucked, eyes wide and darting."] = "s'enfonce lentement, menton rentré, les yeux écarquillés, aux aguets.",
	["sinks lower where they sit, with the long sigh of someone easing into a tub."] = "s'enfonce un peu plus à sa place, avec le long soupir de quelqu'un qui se glisse dans un bain.",
	["sinks slowly downward with a look of deep calm, cheeks not puffed at all."] = "s'enfonce lentement avec un air de calme profond, sans gonfler les joues le moins du monde.",
	["sits back from the fire and lets the story settle."] = "se recule du feu et laisse l'histoire faire son chemin.",
	["sits perfectly still, one arm still raised from the throw."] = "reste parfaitement immobile, un bras encore levé après le lancer.",
	["sits up straight and raises one hand, palm out, like someone refusing a request."] = "se redresse et lève une main, paume en avant, comme pour opposer un refus.",
	["sits up suddenly and listens, one hand raised for silence."] = "se redresse d'un coup et écoute, une main levée pour réclamer le silence.",
	["sits up very slowly, arms stiff at their sides, staring ahead."] = "se redresse très lentement, les bras raides le long du corps, le regard fixe.",
	["sits up very straight, eyes fixed on something far past the firelight."] = "se redresse bien droit, les yeux fixés sur quelque chose, loin au-delà de la lueur du feu.",
	["sits up very straight, folds their arms, and closes their eyes."] = "se tient bien droit, croise les bras et ferme les yeux.",
	["sits up with their chin level and shoulders still, as if a brimming bowl rested on their head."] = "se redresse, le menton droit et les épaules immobiles, comme si un bol plein à ras bord reposait sur sa tête.",
	["sits very still, the firelight moving over a face that does not."] = "reste parfaitement immobile, la lueur du feu jouant sur un visage qui, lui, ne bouge pas.",
	["sketches a huge curve in the air with one finger."] = "dessine une immense courbe dans l'air du bout du doigt.",
	["sketches a weary sign of blessing in the air, like someone swatting a fly."] = "trace dans l'air un signe de bénédiction las, comme on chasse une mouche.",
	["slaps at their neck, then their arm, then flails at the empty air."] = "se donne une claque sur la nuque, puis sur le bras, puis bat l'air à grands gestes.",
	["slashes left, slashes right, then throws an arm up against an imaginary blow."] = "taille à gauche, taille à droite, puis lève un bras contre un coup imaginaire.",
	["slides half of an invisible stack of coins toward themselves, leaving the rest."] = "ramène la moitié d'une pile de pièces invisible et laisse le reste.",
	["slides three invisible cups around on the ground, fast."] = "fait glisser trois gobelets invisibles sur le sol, à toute vitesse.",
	["slowly lowers their hands and wipes them on their knees."] = "baisse lentement les mains et les essuie sur ses genoux.",
	["slowly raises their eyes upward, then lowers them again."] = "lève lentement les yeux, puis les rabaisse.",
	["slowly tips their shoulders to the wrong side and holds there, looking uneasy."] = "incline lentement les épaules du mauvais côté et reste ainsi, l'air mal à l'aise.",
	["slumps sideways with their tongue out and eyes rolled up, perfectly still."] = "s'effondre sur le côté, la langue pendante et les yeux révulsés, sans bouger d'un poil.",
	["smiles a little into their cup and lets the joke stand."] = "sourit un peu dans sa tasse et laisse la blague retomber toute seule.",
	["smiles and lays a hand flat over their heart."] = "sourit et pose une main à plat sur son cœur.",
	["smiles at the fire."] = "sourit aux flammes.",
	["smiles at {target} a little too brightly."] = "sourit à {target} un peu trop largement.",
	["smiles down at a folded scrap of paper they clearly cannot read."] = "contemple en souriant un bout de papier plié dont les lettres restent un mystère.",
	["smiles into the fire, and doesn't say anything for a moment."] = "sourit au feu et reste un moment sans rien dire.",
	["smiles into the fire."] = "sourit, les yeux dans le feu.",
	["smiles thinly and looks away, shifting so the firelight doesn't quite reach their face."] = "esquisse un mince sourire et détourne les yeux, en se décalant pour que la lueur du feu n'atteigne pas tout à fait son visage.",
	["smiles to themselves."] = "sourit en silence.",
	["smooths a fold of cloth across one knee, slowly, and leaves their hand resting on it."] = "lisse lentement un pli d'étoffe sur un genou, et y laisse la main posée.",
	["smooths a patch of ground flat with the palm of one hand."] = "lisse un coin de terre du plat de la main.",
	["smooths down the front of their shirt with a small, pleased smile."] = "lisse le devant de sa chemise avec un petit sourire satisfait.",
	["smooths down their hair, looking faintly worried."] = "se lisse les cheveux, l'air vaguement inquiet.",
	["snaps a thorny branch for the fire, sucks a pricked thumb, and nods as if the point were proved."] = "casse une branche épineuse pour le feu, se pique le pouce, le suce, et hoche la tête comme si la démonstration était faite.",
	["snaps their fingers, looks pleased, and then lets the smile slowly fade."] = "claque des doigts, l'air satisfait, puis laisse le sourire s'effacer lentement.",
	["snatches at something on the ground, then hunches low with an arm over their head."] = "attrape vivement quelque chose par terre, puis se recroqueville, un bras par-dessus la tête.",
	["snatches up a stick and scrawls furiously in the ashes, as if it were a stub of chalk."] = "saisit un bâton et griffonne frénétiquement dans les cendres, comme avec un bout de craie.",
	["sneezes enormously, then looks around in horror."] = "éternue de façon monumentale, puis jette des regards horrifiés alentour.",
	["sniffs one wrist, winces, and wipes it on their knee."] = "renifle son poignet, grimace, et l'essuie sur son genou.",
	["sniffs the air once, then stops, and presses their lips together."] = "renifle l'air une fois, puis s'arrête et serre les lèvres.",
	["sniffs the air, then slowly turns their head to look behind them."] = "renifle l'air, puis tourne lentement la tête pour regarder en arrière.",
	["spreads both hands, palms up, and lifts them slowly."] = "écarte les deux mains, paumes vers le ciel, et les soulève lentement.",
	["spreads their arms wide and hisses, then looks faintly embarrassed."] = "écarte grand les bras et siffle, puis prend un air vaguement gêné.",
	["spreads their arms wide and wobbles, trying to keep their balance."] = "écarte grand les bras et vacille, en essayant de garder l'équilibre.",
	["spreads their hands in a gesture of complete and final innocence."] = "écarte les mains dans un geste d'innocence totale et définitive.",
	["spreads their hands wider and wider apart, as if measuring a raptor that keeps growing."] = "écarte les mains de plus en plus, comme pour mesurer un raptor qui ne cesse de grandir.",
	["spreads their hands wider and wider, then slowly draws them back into their lap."] = "écarte les mains de plus en plus, puis les ramène lentement sur ses genoux.",
	["spreads their hands, still honestly troubled by the question."] = "écarte les mains, encore sincèrement perplexe.",
	["squares their shoulders and raises one arm, as if a shield still hung from it."] = "carre les épaules et lève un bras, comme si un bouclier y pendait encore.",
	["squints across the fire at {target}, tilting their head one way and then the other."] = "plisse les yeux en regardant {target} par-dessus le feu, la tête penchée d'un côté, puis de l'autre.",
	["squints along the rim of an invisible mug, deeply unconvinced."] = "examine le bord d'une chope invisible en plissant les yeux, avec la plus profonde méfiance.",
	["squints and rubs their temples with both hands."] = "plisse les yeux et se masse les tempes des deux mains.",
	["squints at the coals with a smith's eye, plainly unimpressed, then grins."] = "jauge les braises d'un œil de forgeron, avec une moue qui en dit long, puis sourit.",
	["stares at nothing in particular for a while before speaking."] = "fixe le vide un moment avant de parler.",
	["stares blankly ahead, imitating a whole room of unamused faces."] = "fixe le vide d'un air morne, en imitant toute une salle de visages de marbre.",
	["stares down at an invisible bowl, a spoon halfway to their mouth."] = "fixe un bol invisible, la cuillère à mi-chemin de la bouche.",
	["stares hard into the dark beyond the fire, without blinking."] = "scrute le noir au-delà du feu, sans cligner des yeux.",
	["stares into the coals for a long moment."] = "fixe les braises un long moment.",
	["stares into the fire a while before looking up again."] = "fixe le feu un moment avant de relever les yeux.",
	["stares into the fire, as if it might have an answer of its own."] = "fixe le feu, comme s'il pouvait avoir sa propre réponse.",
	["stares into the flames and doesn't blink for a while."] = "fixe les flammes et ne cligne plus des yeux pendant un moment.",
	["stares into the sullen, smoking fire, and takes their time before going on."] = "fixe le feu maussade et fumant, et prend son temps avant de reprendre.",
	["stays very still, head cocked toward the dark, as though for two soft notes."] = "reste immobile, la tête tournée vers le noir, comme à l'affût de deux notes douces.",
	["steps their hands forward through the air, one flat palm after the other, testing each one."] = "fait avancer ses mains dans l'air, une paume à plat après l'autre, en tâtant chaque pas.",
	["stirs an invisible pot with growing effort, then stops, the spoon stuck fast."] = "remue une marmite invisible avec de plus en plus de peine, puis s'arrête, la cuillère coincée pour de bon.",
	["stirs the coals with a stick, lips still moving."] = "attise les braises avec un bâton, les lèvres remuant toujours.",
	["stops fiddling with a small gear and just holds it."] = "arrête de tripoter un petit engrenage et se contente de le tenir.",
	["stops moving entirely, barely breathing, eyes fixed on the dark."] = "s'immobilise complètement, respirant à peine, les yeux rivés sur le noir.",
	["stops talking and holds very still for a moment."] = "s'interrompt et reste parfaitement immobile un instant.",
	["stops talking and looks just past {target}'s shoulder."] = "s'interrompt et regarde juste derrière l'épaule de {target}.",
	["straightens their back, chin high, one hand flat over the heart."] = "se redresse, le menton haut, une main à plat sur le cœur.",
	["straightens their collar and attempts an expression of great respectability."] = "redresse son col et tente de prendre un air de grande respectabilité.",
	["straightens their own collar, then straightens it again, more carefully."] = "redresse son propre col, puis le redresse encore, plus soigneusement.",
	["stretches and settles back, ready for sleep."] = "s'étire et se cale en arrière, en attendant le sommeil.",
	["stretches their hands toward a fire, then slowly draws them back."] = "tend les mains vers un feu, puis les retire lentement.",
	["stretches their mouth into a stiff, uncertain grin, then lets it drop."] = "étire sa bouche en un sourire raide et hésitant, puis le laisse retomber.",
	["stretches their shoulders and lets out a slow, contented breath."] = "étire les épaules et laisse échapper un long souffle satisfait.",
	["strikes their hands together sharply, then shields their eyes from a sudden blaze."] = "frappe sèchement ses mains l'une contre l'autre, puis se protège les yeux d'un brasier soudain.",
	["studies {target} across the fire with a thoughtful frown."] = "observe {target} par-dessus le feu, les sourcils froncés, l'air songeur.",
	["sways a little where they sit, as if to slow music."] = "se balance un peu sans se lever, comme sur une musique lente.",
	["sways gently where they sit, wearing a look of perfect trust."] = "se balance doucement sans se lever, avec un air de confiance absolue.",
	["swings an arm wildly at nothing, falling just short, then lets it drop."] = "lance le bras dans le vide, manque son but de peu, puis le laisse retomber.",
	["swings an imaginary pick, slowly, then rubs the small of their back with a groan."] = "abat lentement une pioche imaginaire, puis se frotte les reins avec un grognement.",
	["swings an invisible tool down onto the ground."] = "abat un outil invisible sur le sol.",
	["swings one arm in a wide loop over their head and lets something fly."] = "fait tournoyer un bras en grande boucle au-dessus de sa tête et lâche quelque chose.",
	["takes a bite of the apple, chews, and pitches the core into the fire, where it hisses."] = "croque dans la pomme, mâche, et jette le trognon au feu, où il siffle.",
	["takes a sip from their cup and makes a sour face."] = "boit une gorgée dans sa tasse et fait la grimace.",
	["takes a split log from the firewood, knocks twice on it, and listens to the sound."] = "prend une bûche fendue dans le tas de bois, frappe deux fois dessus et écoute le son.",
	["takes a worn, much-folded letter from a pouch and smooths it out."] = "sort d'une bourse une lettre usée, pliée et repliée, et la défroisse.",
	["takes off one boot, turns it over, and watches a thin stream of sand patter into the fire."] = "retire une botte, la retourne et regarde un mince filet de sable crépiter dans le feu.",
	["takes out a small stoppered jar and tilts it toward the light."] = "sort un petit bocal bouché et l'incline vers la lumière.",
	["takes something small from a pocket, looks at it, and puts it carefully away again."] = "sort quelque chose de petit d'une poche, le regarde, et le range soigneusement.",
	["taps a finger against their chin."] = "se tapote le menton du doigt.",
	["taps a fingernail once against the rim of a cup, then listens."] = "tapote une fois le bord d'une tasse du bout de l'ongle, puis tend l'oreille.",
	["taps a knuckle gently against an invisible stone, and tilts their head as if listening."] = "tapote doucement une pierre invisible du bout des phalanges, et penche la tête comme pour écouter.",
	["taps a slow rhythm on their own knee with both hands, eyes closed."] = "tapote lentement un rythme sur son genou, des deux mains, les yeux fermés.",
	["taps a small imaginary gavel, then flinches at the sound."] = "frappe un petit maillet imaginaire, puis sursaute au bruit.",
	["taps one knuckle against a piece of firewood and listens."] = "tape une phalange contre une bûche et tend l'oreille.",
	["taps out a slow rhythm with one finger: long, short, short."] = "tape un rythme lent du bout d'un doigt : long, court, court.",
	["taps the side of their cup to get everyone's attention."] = "tapote le bord de sa tasse pour attirer l'attention de tous.",
	["taps the side of their cup, slow and even, like someone counting."] = "tapote le flanc de sa tasse, lentement, régulièrement, comme pour compter.",
	["taps the side of their nose twice."] = "se tapote deux fois l'aile du nez.",
	["taps their chin, thinking, then spreads their hands helplessly."] = "se tapote le menton d'un air songeur, puis écarte les mains d'un geste désarmé.",
	["taps twice on something unseen, then quickly pulls their hand away."] = "tapote deux fois sur quelque chose d'invisible, puis retire vite sa main.",
	["taps two fingers against their chest, where a badge might have hung."] = "se tapote la poitrine de deux doigts, là où un insigne aurait pu pendre.",
	["taps two fingers slowly against their temple."] = "se tapote lentement la tempe de deux doigts.",
	["tears a piece of bread in two, looking at it thoughtfully."] = "déchire un morceau de pain en deux et le regarde pensivement.",
	["tears an invisible strip of meat in two and offers half across a fire."] = "déchire en deux une lanière de viande invisible et en tend la moitié par-dessus un feu.",
	["tests a knot with both hands, then tests it again."] = "éprouve un nœud des deux mains, puis l'éprouve encore.",
	["the first thing you'll mine when you're new to the town. What am I?"] = "le premier qu'on extrait quand on débute, sans fortune. Qui suis-je ?",
	["the gold, and then I'll carry you over the ground. What am I?"] = "puis, l'or enfin trouvé, je vous porterai sur le chemin. Qui suis-je ?",
	["the whole city asks if they've heard about you. What am I?"] = "on ne parle que de moi en ville, et ça rend les gens furieux. Qui suis-je ?",
	["then rise with my help on a borrowed breath. What am I?"] = "puis, d'un souffle emprunté, grâce à moi, revit encore. Qui suis-je ?",
	["throws both arms out as if skidding to a stop, and stares down in horror."] = "écarte les bras comme pour freiner en dérapant, et baisse les yeux avec horreur.",
	["throws both arms up as if in front of a roaring crowd."] = "lève les deux bras, comme devant une foule en délire.",
	["throws one arm over their face and leans hard into nothing, gritting their teeth."] = "se couvre le visage d'un bras et s'arc-boute contre le vide, les dents serrées.",
	["throws themselves sideways with a great splash of both hands."] = "se jette de côté en faisant gicler une grande gerbe d'eau des deux mains.",
	["throws up their hands and laughs at the fire."] = "lève les bras au ciel et rit devant le feu.",
	["thumps a fist against their own chest and listens to the sound."] = "se frappe la poitrine du poing et écoute le bruit.",
	["ties a neat knot in a bit of string without looking, then pulls it loose."] = "fait un nœud net dans un bout de ficelle sans regarder, puis tire dessus pour le défaire.",
	["ties the knot again, and this time leaves it tied."] = "refait le nœud, et cette fois le laisse noué.",
	["tilts an invisible cup slowly sideways and watches it with great suspicion."] = "incline lentement une tasse invisible et la surveille d'un œil très méfiant.",
	["tilts slowly to one side, holds it for a moment, then straightens with a sigh."] = "s'incline lentement sur le côté, reste ainsi un moment, puis se redresse avec un soupir.",
	["tilts their face to the sky with their eyes closed and their palms up."] = "lève le visage vers le ciel, les yeux fermés et les paumes ouvertes.",
	["tilts their head and leans it against the empty air, as though resting one ear on something huge."] = "penche la tête et l'appuie contre le vide, comme pour poser l'oreille sur quelque chose d'immense.",
	["tilts their head back and stares at the sky."] = "renverse la tête en arrière et fixe le ciel.",
	["tilts their head back, as though looking up into tall branches."] = "renverse la tête en arrière, comme pour regarder de hautes branches.",
	["tilts their head sideways and clears their throat with exaggerated courtesy."] = "penche la tête de côté et s'éclaircit la gorge avec une politesse exagérée.",
	["tilts their head sideways and tugs gently at nothing, with growing concern."] = "penche la tête de côté et tire doucement sur le vide, avec une inquiétude croissante.",
	["tilts their head slightly, as though hearing something faint."] = "penche légèrement la tête, comme pour saisir un son à peine audible.",
	["tilts their head toward the dark and attempts an innocent expression."] = "penche la tête vers l'obscurité et tente de prendre un air innocent.",
	["tilts their head toward the ground and listens, not moving at all."] = "incline la tête vers le sol et écoute, sans bouger d'un pouce.",
	["tilts their head, as though listening for rain on a roof far from here."] = "penche la tête, comme pour écouter la pluie sur un toit, loin d'ici.",
	["tilts their head, listening, and holds up one finger for silence."] = "penche la tête, aux aguets, et lève un doigt pour demander le silence.",
	["tilts their head, wearing a look of gentle confusion."] = "penche la tête, l'air doucement perplexe.",
	["tips a little from their waterskin onto the ground beside them, and says nothing more."] = "verse un peu de sa gourde sur le sol, juste à côté, et n'ajoute rien.",
	["tips an imaginary hat toward the darkness."] = "soulève un chapeau imaginaire en direction du noir.",
	["tips their head back and goes quiet, gazing straight up."] = "renverse la tête en arrière et se tait, les yeux levés droit vers le ciel.",
	["tosses a dry twig into the flames and watches how quickly it is gone."] = "jette une brindille sèche dans les flammes et regarde avec quelle vitesse elle disparaît.",
	["tosses a small bone into the fire with great bitterness."] = "jette un petit os dans le feu avec une immense amertume.",
	["tosses an apple up and catches it without looking."] = "lance une pomme en l'air et la rattrape sans regarder.",
	["touches one finger to an imaginary jug and frosts it with tremendous solemnity."] = "pose un doigt sur une cruche imaginaire et la couvre de givre avec une solennité extraordinaire.",
	["touches their rolled bedding, then draws their hands back toward the warmth."] = "touche sa couverture roulée, puis ramène les mains vers la chaleur.",
	["touches two fingers to the ground, then to their heart."] = "pose deux doigts sur le sol, puis sur son cœur.",
	["traces a few letters in the dirt with one finger, then wipes them away."] = "trace quelques lettres dans la terre du bout du doigt, puis les efface.",
	["traces a few slow letters in the air with one finger."] = "trace lentement quelques lettres dans l'air du bout du doigt.",
	["traces a line across an invisible page, lips moving silently."] = "suit une ligne du doigt sur une page invisible, en remuant les lèvres sans un bruit.",
	["traces a line across their palm with one finger, then taps it with a knuckle."] = "trace une ligne en travers de sa paume du bout du doigt, puis la tapote d'une phalange.",
	["traces a little patch shape in the air and goes still."] = "dessine en l'air la forme d'une petite pièce, et ne bouge plus.",
	["traces a long, winding shape across the sky with one finger."] = "trace du doigt une longue forme sinueuse dans le ciel.",
	["tucks something small into an invisible crack, glancing left and right."] = "glisse un petit quelque chose dans une fissure invisible, en jetant un œil à gauche et à droite.",
	["tucks the cord away and looks out past the firelight."] = "range la cordelette et regarde au-delà de la lueur du feu.",
	["tucks the folded paper into a pocket, close to their heart."] = "glisse la feuille pliée dans une poche, tout près du cœur.",
	["tucks the invisible button into a pocket and pats it."] = "glisse le bouton invisible dans une poche et la tapote.",
	["tucks the jar away again, gently, and pats the pocket twice."] = "range à nouveau le bocal, doucement, et tapote deux fois la poche.",
	["tucks their elbows in tight and works both hands in a small space, feeling for something."] = "serre les coudes contre le corps et manœuvre des deux mains dans un espace exigu, à tâtons.",
	["tugs at a lead rope, then lets it go slack."] = "tire sur une longe, puis la laisse retomber, détendue.",
	["tugs at their sleeve and checks the stitching, as if for the hundredth time."] = "tire sur sa manche et vérifie la couture, comme pour la centième fois.",
	["turns a cup slowly in their hands, not drinking."] = "fait lentement tourner une tasse entre ses mains, sans boire.",
	["turns a flat stone over in their fingers, as if looking for water to skip it on."] = "fait tourner une pierre plate entre ses doigts, comme en quête d'une eau où faire des ricochets.",
	["turns a folded paper over in their hands without opening it."] = "tourne et retourne un papier plié entre ses mains, sans l'ouvrir.",
	["turns a pebble over and sets it down without a sound."] = "retourne un caillou entre ses doigts et le repose sans un bruit.",
	["turns a small stone in their fingers, looking over at {target}."] = "fait tourner un petit caillou entre ses doigts, le regard posé sur {target}.",
	["turns a small, invisible package over in their hands."] = "retourne entre ses mains un petit paquet invisible.",
	["turns a smooth gray pebble over in their fingers."] = "fait rouler un galet gris et lisse entre ses doigts.",
	["turns a stick over in the coals and does not look up."] = "retourne un bâton dans les braises sans lever les yeux.",
	["turns an invisible knot over in their fingers, slowly, examining it."] = "tourne et retourne lentement un nœud invisible entre ses doigts, pour l'examiner.",
	["turns an invisible page, slowly, and runs a finger down it."] = "tourne lentement une page invisible et y fait glisser un doigt.",
	["turns an invisible page, slowly, then stops and does not turn the next one."] = "tourne lentement une page invisible, puis s'arrête et ne tourne pas la suivante.",
	["turns invisible pages, slowly, one at a time."] = "tourne des pages invisibles, lentement, une à une.",
	["turns one hand over slowly, as if holding something small and bright."] = "retourne lentement une main, comme si elle tenait quelque chose de petit et de brillant.",
	["turns one hand over slowly, palm down, and lays it flat."] = "retourne lentement une main, paume vers le bas, et la pose à plat.",
	["turns one hand palm up, then palm down, and stares at it."] = "tourne une main paume vers le haut, puis paume vers le bas, et la fixe longuement.",
	["turns one open hand toward the other, leaving a little space between them."] = "tourne une main ouverte vers l'autre, en laissant un petit espace entre elles.",
	["turns one palm over and studies it for a while."] = "retourne une main, paume en l'air, et la contemple un long moment.",
	["turns one palm upward as though weighing a leaf, then closes their fingers."] = "tourne une paume vers le ciel comme pour soupeser une feuille, puis referme les doigts.",
	["turns out one empty pocket, then the other, and sighs."] = "retourne une poche vide, puis l'autre, et soupire.",
	["turns over something small on the ground with one finger, and watches it crawl away."] = "retourne du bout du doigt quelque chose de minuscule par terre, et le regarde s'éloigner en rampant.",
	["turns partway from the fire, then stops and glances back over one shoulder into the dark."] = "se détourne à demi du feu, puis s'arrête et jette un regard par-dessus son épaule, vers le noir.",
	["turns the blade so the firelight slides along its edge, and looks at it for a while."] = "tourne la lame pour que la lueur du feu glisse le long du fil, et la regarde un long moment.",
	["turns the invisible letter around and holds it out so the writing faces {target}."] = "retourne la lettre invisible et la tend pour que l'écriture soit face à {target}.",
	["turns the wood to the firelight, then takes off another curl and flicks it into the flames."] = "tourne le bois vers la lueur du feu, puis enlève un autre copeau et l'envoie d'une pichenette dans les flammes.",
	["turns their face away and hunches their shoulders against a blast of wind."] = "détourne le visage et rentre les épaules face à une rafale de vent.",
	["turns their face beyond the firelight and pauses as though an answer is still owed."] = "détourne le visage vers l'ombre, au-delà du feu, et s'arrête, comme si on attendait encore une réponse.",
	["turns their face up, as if into a strong wind, and speaks a few silent words."] = "lève le visage comme face à un vent violent, et prononce quelques mots sans un son.",
	["turns their head by slow degrees until they're looking over one shoulder."] = "tourne la tête, petit à petit, jusqu'à regarder par-dessus son épaule.",
	["turns their head to the side and stares with one unblinking eye."] = "tourne la tête de côté et fixe l'assemblée d'un seul œil, sans ciller.",
	["turns their head toward the empty air beside them, and holds very still."] = "tourne la tête vers le vide, à ses côtés, et ne bouge plus.",
	["turns to {target} and opens one hand, palm up."] = "se tourne vers {target} et ouvre une main, paume vers le ciel.",
	["turns to {target}, speaking more softly now."] = "se tourne vers {target} et parle plus doucement.",
	["twirls one finger in a tight little circle, then points sharply."] = "fait tourner un doigt en un petit cercle serré, puis le pointe droit devant, d'un coup sec.",
	["twists an invisible handful of grass together and ties it off with care."] = "tord ensemble une poignée d'herbe invisible et la noue avec soin.",
	["twists one fist slowly, as if turning a stiff post in the ground."] = "tord lentement le poing, comme pour faire pivoter un poteau planté dans la terre.",
	["twists their whole body and yanks hard on a strap."] = "se tord de tout son corps et tire d'un coup sec sur une sangle.",
	["twitches their nose and jerks their head around, wide-eyed, at nothing."] = "remue le nez et tourne vivement la tête, les yeux écarquillés, vers rien du tout.",
	["unfolds a scrap of paper and holds it up for all to admire."] = "déplie un bout de papier et le brandit pour que tout le monde l'admire.",
	["unfolds an invisible stool with great pride and pats the top of it."] = "déplie un tabouret invisible avec une immense fierté et en tapote l'assise.",
	["unrolls a map and smooths it flat with both hands."] = "déroule une carte et l'aplatit des deux mains.",
	["wags a finger across the fire at {target}."] = "agite un doigt en direction de {target} par-dessus le feu.",
	["waits while a log settles in the fire with a low thud, and does not seem to like the sound."] = "attend qu'une bûche s'affaisse dans le feu avec un bruit sourd, et ce bruit n'a pas l'air de lui plaire.",
	["walks two fingers briskly off the edge of one knee, then winces all the way down."] = "fait marcher vivement deux doigts jusqu'au bord d'un genou, puis grimace pendant toute la descente.",
	["watches a log settle in the fire and does not look up for a moment."] = "regarde une bûche s'affaisser dans le feu et ne relève pas les yeux pendant un moment.",
	["watches a log settle in the fire and does not speak again."] = "regarde une bûche se tasser dans le feu, et ne dit plus rien.",
	["watches a slow ripple of heat cross the coals, and lets it fade."] = "regarde une lente onde de chaleur traverser les braises, et la laisse s'éteindre.",
	["watches one spark circle up above the flames, around and around, until it winks out."] = "suit des yeux une étincelle qui tourne au-dessus des flammes, encore et encore, jusqu'à ce qu'elle s'éteigne.",
	["watches something roll slowly past, following it with one pointing finger."] = "suit du doigt quelque chose qui passe en roulant, tout doucement.",
	["watches the fire for a while, the way one might watch a lit window from outside."] = "regarde le feu un moment, comme on regarde une fenêtre éclairée depuis la rue.",
	["watches the smoke climb as it might from a chimney, and is the first to look away."] = "regarde la fumée monter, comme elle monterait d'une cheminée, et détourne les yeux avant tout le monde.",
	["watches the smoke drift off into the dark for a long while."] = "regarde longuement la fumée s'éloigner dans le noir.",
	["watches the smoke drift toward the listeners, scowls, and waves it back."] = "regarde la fumée dériver vers l'auditoire, fronce les sourcils et la chasse d'un geste.",
	["watches the smoke lean one way, then the other, and nods as if it had spoken."] = "regarde la fumée pencher d'un côté, puis de l'autre, et hoche la tête comme si elle avait parlé.",
	["watches the space behind {target} for a long, slow moment, then looks back to the flames."] = "fixe l'espace derrière {target} un long moment, puis revient aux flammes.",
	["watches the sparks climb until the last one goes out."] = "regarde les étincelles monter jusqu'à ce que la dernière s'éteigne.",
	["watches the sparks go up into the dark and lets the moment hang."] = "regarde les étincelles monter dans le noir et laisse le silence s'installer.",
	["watches the sparks lift off the fire and drift away into the dark, one by one."] = "regarde les étincelles quitter le feu et s'éloigner dans le noir, une à une.",
	["watches which way the smoke leans, and does not remark on it."] = "regarde de quel côté penche la fumée, et n'en dit rien.",
	["waves a hand in front of their face and coughs politely."] = "agite une main devant son visage et tousse poliment.",
	["waves a hand in front of their nose."] = "agite une main devant son nez.",
	["weighs the seed over the flames for a moment, then closes their fingers around it and puts it away."] = "soupèse la graine au-dessus des flammes un instant, puis referme les doigts dessus et la range.",
	["wets a finger, holds it up, and slowly turns to face the other way."] = "mouille un doigt, le lève, et se retourne lentement dans l'autre sens.",
	["whips an invisible rope around something twice and leans back hard with both hands."] = "enroule vivement deux fois une corde invisible autour de quelque chose et se penche en arrière de toutes ses forces, à deux mains.",
	["wiggles two fingers at the fire, and the flames happen to give a small, weary dance."] = "agite deux doigts vers le feu, et les flammes, comme par hasard, esquissent une petite danse fatiguée.",
	["winces at the memory, then laughs quietly to themselves."] = "grimace à ce souvenir, puis laisse échapper un petit rire.",
	["winds up and throws something hard and high, then holds very still, watching."] = "prend son élan et lance quelque chose haut et fort, puis s'immobilise, les yeux fixés au loin.",
	["wipes the last circle out of the ashes with one fingertip."] = "efface le dernier cercle dans la cendre du bout du doigt.",
	["wipes their hands slowly on their knees, as if they can't quite get them clean."] = "s'essuie lentement les mains sur les genoux, comme si elles refusaient de redevenir tout à fait propres.",
	["wraps both hands around their cup with one thumb hooked over the rim, and looks at it."] = "entoure sa tasse des deux mains, un pouce passé par-dessus le bord, et la regarde.",
	["wraps one hand slowly around the other."] = "enveloppe lentement une main dans l'autre.",
	["wrenches an invisible rail free with both hands and drives it forward and down."] = "arrache des deux mains une barre invisible et la plante en avant, vers le bas.",
	["wrings out the end of their sleeve and looks at it without hope."] = "essore le bout de sa manche et la regarde sans le moindre espoir.",
	["wrings out the hem of one sleeve, laughing."] = "essore le bord d'une manche en riant.",
	["wrinkles their nose and holds an invisible shard at arm's length."] = "fronce le nez et tient un éclat invisible à bout de bras.",
	["wrinkles their nose and leans slowly away from their own armpit."] = "fronce le nez et s'écarte lentement de sa propre aisselle.",
	["writes a line of small, tidy letters in the ashes with a stick, and leaves the last word unfinished."] = "trace avec un bâton une ligne de petites lettres soignées dans la cendre, et laisse le dernier mot inachevé.",
	["yanks an invisible strap twice, then lets it go with a sigh."] = "tire deux fois d'un coup sec sur une sangle invisible, puis la lâche en soupirant.",
	["yanks one hand sharply backward, then stares at the empty space in front of them."] = "tire brusquement une main en arrière, puis fixe l'endroit vide, juste devant.",
	["yet hold me and wait, and I'll bring you back home. What am I?"] = "mais tenez-moi, patientez, et vous voilà de retour chez vous. Qui suis-je ?",
	["your bags"] = "vos sacs",
	["{target}, I should warn you. People have been talking."] = "{target}, je dois vous prévenir. Les gens parlent.",
	["{target}, an old friend and I have argued for years over whether soup is a food or a drink. We've ruined a lot of good soup over it."] = "{target}, une vieille amie et moi, on se dispute depuis des années pour savoir si la soupe se mange ou se boit. On a gâché beaucoup de bonne soupe à cause de ça.",
	["{target}, would you mind if I told you something about where you're sitting? It's nothing bad. Probably."] = "{target}, ça vous ennuie si je vous dis quelque chose sur la place où vous êtes ? Rien de grave. Sans doute.",
	["{target}, you seem sensible, so I'll tell you what I tell everyone who eats at my fire."] = "{target}, vous avez l'air raisonnable, alors je vais vous dire ce que je dis à tous ceux qui mangent à mon feu.",
})
